"use strict";exports.id=9060,exports.ids=[9060],exports.modules={69060:(a,b,c)=>{c.d(b,{O:()=>s});let d="/images/ms-office/onedrive/module-1",e=(a,b)=>b.map((b,c)=>({src:`${d}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),f=[{slug:"what-is-onedrive",title:"What OneDrive Is and When to Use It",description:"Learn what cloud storage is, what OneDrive does for you at work, how it relates to SharePoint and Teams, and where patient information is and is not allowed to go.",objectives:["Explain cloud storage and what OneDrive adds: access anywhere, sharing, version history, the Recycle bin, and syncing","Tell the difference between your OneDrive and a shared team library in SharePoint or Teams","Describe how much storage free, Microsoft 365, and work accounts include","Apply the rule that patient information stays in approved work locations and is never shared with an Anyone link"],duration:"15 min",slides:e("what-is-onedrive",["What OneDrive is: Microsoft's cloud storage for your files","Five things OneDrive does for you at the front desk","OneDrive, SharePoint, and Teams: whose files live where","How much storage each kind of account includes","The patient information rule: approved places only, never an Anyone link","Quick check: OneDrive or a team library?"]),sections:[{heading:"Your files, wherever you sign in",blocks:[{type:"scenario",role:"You are a front office assistant at Lakeside Medical Associates.",text:"Last month the computer at the second check-in window stopped starting. Everything saved on its desktop, including the only copy of the new-patient phone script, was gone. Lakeside has now moved everyone to Microsoft 365, and your office manager, Maria Santos, has a new rule: work files are saved to OneDrive or the shared team library, not to one computer's desktop or a USB drive.",task:"Understand what OneDrive is, what it protects you from, and which of your files belong in it."},{type:"paragraph",text:"Cloud storage keeps your files on servers that you reach over the internet instead of only on the hard drive inside one computer. OneDrive is Microsoft's cloud storage. You sign in with an account, and your files are there on any computer, phone, or tablet where you sign in with that same account. If a computer breaks, is replaced, or is stolen, the files are still in OneDrive."},{type:"key-terms",terms:[{term:"Cloud storage",definition:"Saving files on internet servers so you can reach them from any device you sign in on."},{term:"OneDrive",definition:"Microsoft's cloud storage. Each person has their own OneDrive."},{term:"Work or school account",definition:"The account your employer or school gives you (for example, amorgan@lakesidemedical.example). The organization manages it."},{term:"Microsoft account",definition:"A personal account you create yourself (often an Outlook.com address). It comes with a personal OneDrive."},{term:"Sync",definition:"Keeping the copy on your PC and the copy in OneDrive the same, automatically."},{term:"SharePoint",definition:"Microsoft's shared storage for teams and whole organizations. Files in a Teams channel are stored in SharePoint."}]}]},{heading:"What OneDrive does for you",blocks:[{type:"table",caption:"OneDrive features and what they mean at the front desk",columns:["Feature","What it does","Front desk example"],rows:[["Access anywhere","Your files open on any device where you sign in","Open the phone script at any check-in window, not only the one where you wrote it"],["Share with a link","People open the one real file instead of an email copy","Maria edits the staff schedule you started, and everyone sees the same version"],["Version history","Earlier versions of a file are kept so you can go back","Someone typed over the November schedule; restore yesterday's version"],["Recycle bin","Deleted files can be restored for a period of time","You deleted the wrong flyer; restore it in seconds"],["Sync with your PC","Your OneDrive appears as a folder in File Explorer","Save from Word straight into OneDrive without a browser"]]},{type:"paragraph",text:"All of these work because there is one copy of the file, in one place, that everyone with permission opens. That is the habit OneDrive asks you to build: save to OneDrive, then share the file, instead of saving to the desktop and emailing copies around."}]},{heading:"OneDrive, SharePoint, and Teams at a glance",blocks:[{type:"paragraph",text:"Microsoft 365 has two main places for files. OneDrive is yours: files you are working on, drafts, and files that belong to your job. A SharePoint site or a Teams team is shared: the front desk team's procedures, the forms everyone uses, and files the whole team owns. When you share a file in a Teams chat, Teams stores it in your OneDrive, in a folder named Microsoft Teams Chat Files. When you add a file to a Teams channel, it is stored in that team's SharePoint site."},{type:"table",caption:"Where a file usually belongs",columns:["Put it in","When","Who owns it"],rows:[["Your OneDrive","Drafts, your own work files, files you share with a few people","You"],["A SharePoint site or Teams channel","Files the whole team uses and keeps, even if you leave","The team"],["A Teams chat","A quick file for the people in that chat (it is saved in your OneDrive)","You"]]},{type:"drag-drop",mode:"sort",title:"OneDrive or the team library?",prompt:"Drag each file to where it belongs at Lakeside.",buckets:[{id:"od",label:"Your OneDrive"},{id:"team",label:"Shared team library (SharePoint or Teams)"}],items:[{id:"a",text:"Your first draft of a new reminder-call script",bucket:"od"},{id:"b",text:"The front desk procedures binder everyone follows",bucket:"team"},{id:"c",text:"Your notes from training on the phone system",bucket:"od"},{id:"d",text:"The approved New Patient Intake Form the whole office prints",bucket:"team"},{id:"e",text:"A spreadsheet you are building before you share it with your manager",bucket:"od"},{id:"f",text:"The holiday coverage schedule the whole team edits",bucket:"team"}],explanation:"Ask who owns the file. If it is your work in progress, it belongs in your OneDrive. If the whole team uses it and it must stay when people change jobs, it belongs in the team's library."},{type:"image",src:`${d}/what-is-onedrive/infographic.png`,alt:"OneDrive at a glance: what OneDrive does, where files belong, storage amounts, and the patient information rule",caption:"Quick reference: OneDrive at a glance."}]},{heading:"How much storage you have",blocks:[{type:"paragraph",text:"Storage depends on the account. A free Microsoft account includes 5 GB. Microsoft 365 Basic includes 100 GB, Microsoft 365 Personal includes 1 TB, and the Family and Premium plans share storage among up to six people. Work and school accounts get the storage their organization sets; for most Microsoft 365 business plans the default is 1 TB per person. You can see how much you have used at the bottom of the left pane in OneDrive on the web."},{type:"callout",variant:"info",text:"One file can be as large as 250 GB in OneDrive. Plans and storage amounts change from time to time, so check Microsoft's OneDrive plans page before you buy anything for yourself."}]},{heading:"Patient information stays in approved places",blocks:[{type:"callout",variant:"warning",text:"Lakeside's rule (and the rule at most medical offices): patient information (PHI) goes only in locations your organization approved, such as your work OneDrive or the practice's SharePoint library, and it is shared only with the specific people who need it. Never put patient information in a personal OneDrive, and never share it with an Anyone link. An Anyone link works for whoever gets it, including people outside the practice."},{type:"paragraph",text:"OneDrive makes sharing easy, which is exactly why the rule matters. In Module 3 you will practice choosing the right kind of link. For now, remember the order of questions: Is this patient information? Is this the approved place for it? Who exactly needs it?"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"The computer at a check-in window fails. Which files can you still open from another computer?",options:["Files saved on that computer's desktop","Files saved in your OneDrive","Files saved on a USB drive left in that computer","None of them until IT repairs the computer"],correctIndex:1,explanation:"OneDrive keeps your files in the cloud, so you sign in on any computer and they are there. Files that were only on the broken computer are only as safe as that computer.",optionRationales:["The desktop of a computer is stored on that computer's drive. If the computer fails, so does that copy.","Correct. Files in OneDrive are stored in the cloud and open on any device where you sign in.","A USB drive is one physical copy. It can be lost, damaged, or left behind.","You don't need to wait for the repair. Files in OneDrive are reachable from any computer you sign in on."]},{type:"knowledge-check",question:"A coworker suggests sharing a patient's referral packet with an Anyone link because it is faster. What is the right response?",options:["Agree, as long as the link has an expiration date","Agree, because only the person you send it to will know the link","Decline: patient information is shared only with the specific people who need it, never with an Anyone link","Decline, and email the packet as an attachment to everyone on the care team instead"],correctIndex:2,explanation:"An Anyone link works for whoever has it, so it can be forwarded, guessed from a shared screen, or opened by the wrong person. Patient information is shared only with named people, from an approved location.",optionRationales:["An expiration date limits how long the link works, but anyone who gets it before then can open the file.","Links get forwarded and pasted. An Anyone link does not check who is opening it.","Correct. Share PHI only with the specific people who need it, from an approved work location.","Emailing copies to everyone spreads extra copies of PHI. Share the one file with the named people who need it."]}]}],challenge:[{type:"paragraph",text:"Look at your own OneDrive. BEOC classroom computers let you sign in to OneDrive with your school account."},{type:"list",ordered:!0,items:["Go to onedrive.com and sign in with your school account (or open microsoft365.com, select the app launcher, then OneDrive).","Find how much storage you have used and how much you have. It is at the bottom of the left pane.","Write down three files or folders in your My files. For each, decide: does it belong in your OneDrive or in a shared team library? Write one sentence explaining why.","Sign out when you are done (select your picture or initials at the top right, then Sign out)."]},{type:"callout",variant:"success",text:"Deliverable: Submit your storage numbers and your three sentences to your instructor or course folder. If you cannot sign in, complete the practice simulation in this lesson and submit its results page (use Print or save results on the finish card)."}]},{slug:"the-onedrive-web-layout",title:"Signing In and Finding Your Way Around",description:"Sign in to OneDrive on the web and learn the layout: the left pane, the Create or upload button, the command bar, views, search, and the details pane.",objectives:["Sign in to OneDrive on the web and sign out on a shared computer","Name what each part of the left pane shows: Home, My files, Shared, Favorites, Recycle bin, People, Meetings, and Media","Use the command bar, the details pane, and the list and tiles views","Search for a file by name"],duration:"15 min",slides:e("the-onedrive-web-layout",["Two ways to sign in: onedrive.com or the Microsoft 365 app launcher","The OneDrive layout: header, left pane, command bar, file list, details pane","The left pane: Home, My files, Shared, Favorites, Recycle bin","Browse files by People, Meetings, and Media","Select a file and the command bar changes","Shared computer? Always sign out"]),sections:[{heading:"Signing in",blocks:[{type:"scenario",role:"You are covering the check-in window at Lakeside Medical Associates.",text:"A patient is waiting while you look for the Office Phone List. You know it is in OneDrive somewhere, but you are on a computer you have never used, and every click feels like a guess.",task:"Learn the OneDrive layout well enough to find any file in a few seconds, on any computer."},{type:"list",ordered:!0,items:["Open a browser and go to onedrive.com. Sign in with your work or school account (at Lakeside, your lakesidemedical.example address).","Or go to microsoft365.com, sign in, select the app launcher (the grid of dots at the top left), and select OneDrive.","Your OneDrive opens. A work or school OneDrive shows your name at the top of the left pane."]},{type:"callout",variant:"warning",text:"On a shared or public computer, always sign out when you finish: select your picture or initials at the top right, then Sign out, and close the browser. Closing only the tab can leave you signed in for the next person."}]},{heading:"The parts of the screen",blocks:[{type:"table",caption:"OneDrive on the web, from top to bottom and left to right",columns:["Part","What it is for"],rows:[["Header","The app launcher, the search box, Settings (gear), Help (?), and your account picture"],["Create or upload","Makes a new folder or Office file, or uploads files and folders. (A personal account shows Add new.)"],["Left pane","Home, My files, Shared, Favorites, Recycle bin, then Browse files by People, Meetings, and Media, and Quick access"],["Command bar","Commands for whatever you select: Share, Copy link, Download, Delete, Move to, Copy to, Rename, and More actions (…)"],["File list","Your files and folders. Switch between list and tiles views at the top right"],["Details pane","Select the information (i) button to see who has access, the file's path, size, and version"]]},{type:"callout",variant:"version",text:"Microsoft is moving the Create or upload button from the top of the left pane to the right side of the page, next to the command bar. If you don't see it on the left, look at the top right of the file list. The choices in it are the same."}]},{heading:"The left pane, view by view",blocks:[{type:"paragraph",text:"Home lists files you opened or edited recently, with filters for Word, Excel, PowerPoint, and PDF. My files is your own OneDrive: your folders and files. Shared shows files others shared with you, and files you shared. Favorites holds files you marked with Add to favorites. Recycle bin holds files you deleted, so you can restore them. Under Browse files by, People groups files by the person you shared them with, Meetings shows files shared in your Teams meetings, and Media gathers your photos and videos. Quick access lists shared team libraries you use often."},{type:"drag-drop",mode:"match",title:"Match each view to what it shows",prompt:"Drag each description onto the view it belongs to.",items:[{id:"home",text:"Home",match:"Files you opened or edited recently"},{id:"myfiles",text:"My files",match:"Your own folders and files"},{id:"shared",text:"Shared",match:"Files others shared with you, and files you shared"},{id:"bin",text:"Recycle bin",match:"Files you deleted, ready to restore"},{id:"people",text:"People",match:"Files grouped by the person you share them with"},{id:"meetings",text:"Meetings",match:"Files shared in your Teams meetings"}],explanation:"When you can't find a file, think about how you last touched it: you opened it (Home), you own it (My files), someone sent it (Shared), it came up in a meeting (Meetings)."}]},{heading:"Selecting, the command bar, and the details pane",blocks:[{type:"paragraph",text:"Click a file's row to select it. A round check box appears at the left of the row; select more check boxes (or hold Ctrl and click) to select several files. The command bar above the list changes to show what you can do with what is selected. Right-clicking a file, or selecting More actions (…) next to its name, shows the same commands in a menu. Select the file's name to open it."},{type:"worked-example",title:"Finding the phone list in a hurry",task:"Open the Office Phone List and check who last changed it, on a computer you have never used.",steps:[{move:"Type phone in the Search box at the top and press Enter.",why:"Search looks through your OneDrive and the files shared with you, so you don't have to remember which folder it is in."},{move:"Select the row for Office Phone List, not the name.",why:"Selecting a row picks the file without opening it, so the command bar and details pane show its information."},{move:"Select the information (i) button at the top right.",why:"The details pane shows who modified the file and when, and who has access, which tells you whether this copy is current."},{move:"Select the file name to open it.",why:"Now you know it is the right file, so opening it is the last step, not a guess."}],result:"The current phone list is open, and you know who updated it last.",takeaway:"Search first, select to check, then open. It is faster than clicking through folders."},{type:"tip",text:"Switch to tiles view (the button at the top right of the list) when you are looking for photos or scanned documents. Switch back to list view to see dates, sizes, and sharing."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Your manager shared a training document with you yesterday, but it isn't in My files. Where should you look first?",options:["Recycle bin","Shared","Media","Favorites"],correctIndex:1,explanation:"Files other people share with you stay in their OneDrive, so they show up under Shared, not in your My files.",optionRationales:["The Recycle bin holds files you deleted. A file someone shared with you isn't there.","Correct. Shared lists files others shared with you.","Media shows your photos and videos, not documents others shared.","Favorites shows only files you marked as favorites yourself."]},{type:"knowledge-check",question:"You finished checking the schedule on the computer in the patient education room. What should you do before you walk away?",options:["Close the OneDrive tab","Minimize the browser","Select your picture or initials, select Sign out, then close the browser","Nothing; OneDrive signs you out automatically"],correctIndex:2,explanation:"Closing a tab can leave you signed in. Sign out, then close the browser, so the next person can't open your OneDrive.",optionRationales:["Closing the tab doesn't sign you out; reopening OneDrive could open your files.","Minimizing leaves everything open for the next person.","Correct. Sign out, then close the browser.","Don't count on that. Sign out yourself on any shared computer."]}]}],challenge:[{type:"paragraph",text:"Practice the layout in your real OneDrive (BEOC classroom computers allow OneDrive sign-in)."},{type:"list",ordered:!0,items:["Sign in at onedrive.com with your school account.","Open each view in the left pane: Home, My files, Shared, Favorites, and Recycle bin. In one sentence each, write what you found (it is fine if a view is empty).","Use Search to find any file by typing part of its name. Select it and open the details pane with the information (i) button. Write down its path and when it was last modified.","Switch between list and tiles view and write which one you prefer for documents, and why.","Sign out and close the browser."]},{type:"callout",variant:"success",text:"Deliverable: Submit your notes to your instructor or course folder. If you cannot sign in, complete this lesson's practice simulation and submit its results page instead."}]},{slug:"work-and-personal-accounts",title:"Work or School Accounts and Personal Accounts",description:"Know which OneDrive you are in, what differs between a work or school account and a personal Microsoft account, and why work files never go in personal storage.",objectives:["Tell a work or school OneDrive from a personal OneDrive by its sign-in, address, and labels","List features that differ: Personal Vault, Photos, Recycle bin retention, and organization sharing rules","Keep work files, and especially patient information, out of personal storage","Remove a work file that ended up in a personal OneDrive"],duration:"12 min",slides:e("work-and-personal-accounts",["Two kinds of OneDrive: work or school, and personal","How to tell which one you are in","What is different: Personal Vault, Photos, the Recycle bin, sharing rules","Work files stay in the work account","Quick check: which account?"]),sections:[{heading:"Two kinds of OneDrive",blocks:[{type:"scenario",role:"You use OneDrive at Lakeside and at home.",text:"At home you open your personal OneDrive to print your child's school form and notice a file you don't remember saving there: Lakeside Staff Schedule - copy.xlsx. Months ago you saved it there to look at on the weekend. It lists every staff member's phone number and shifts, and it doesn't belong in your personal account.",task:"Learn to tell the two OneDrives apart and keep work files where they belong."},{type:"paragraph",text:"A work or school account is created and managed by your organization. Its OneDrive belongs to the organization's Microsoft 365, follows its security and sharing rules, and your IT team can help recover it. A personal Microsoft account is one you created yourself, often with an Outlook.com address. Its OneDrive is yours, with your own storage plan, and your employer has no control over it."},{type:"table",caption:"How to tell which OneDrive you are in",columns:["Clue","Work or school","Personal"],rows:[["The account you signed in with","Your work address (amorgan@lakesidemedical.example)","Your own address (for example, an Outlook.com address)"],["The web address","Usually ends in -my.sharepoint.com","onedrive.live.com"],["The button at the top of the left pane","Create or upload","Add new"],["File Explorer folder name","OneDrive - Lakeside Medical Associates","OneDrive - Personal"]]}]},{heading:"What is different",blocks:[{type:"table",caption:"Features that differ by account",columns:["Feature","Work or school","Personal"],rows:[["Recycle bin","Deleted items are kept 93 days, unless your organization changed this","Deleted items are kept 30 days"],["Personal Vault","Not available","A protected folder that needs identity verification to open"],["Photos","Photos appear under Media","A Photos view for your camera pictures"],["Sharing rules","Your organization decides which link types you can use","You decide (some options need a Microsoft 365 subscription)"],["Can't download permission","Available","Not available"]]},{type:"callout",variant:"info",text:"Because your organization manages your work account, your work OneDrive can change when your job changes. When people leave an organization, their work account is usually closed. That is another reason team files belong in a team library, not in one person's OneDrive."}]},{heading:"Work files stay in the work account",blocks:[{type:"paragraph",text:"Copying work files into a personal account feels harmless, but it moves the file outside every protection your organization set up: its security rules, its retention, its ability to remove access when you leave. For a medical office, a work file in a personal account can also be a privacy problem. If you need a work file at home, open it in your work OneDrive by signing in with your work account (if your organization allows it), and don't save a copy anywhere else."},{type:"drag-drop",mode:"sort",title:"Which account?",prompt:"Sort each file into the OneDrive where it belongs.",buckets:[{id:"work",label:"Work OneDrive"},{id:"personal",label:"Personal OneDrive"}],items:[{id:"a",text:"Lakeside staff schedule with phone numbers",bucket:"work"},{id:"b",text:"Your own resume",bucket:"personal"},{id:"c",text:"Insurance verification checklist for the front desk",bucket:"work"},{id:"d",text:"Photos from your family's vacation",bucket:"personal"},{id:"e",text:"A patient's scanned insurance card",bucket:"work"},{id:"f",text:"Your car insurance card",bucket:"personal"}],explanation:"Anything about the practice, its staff, or its patients stays in the work account. Your own documents and photos go in your personal account."},{type:"worked-example",title:"Cleaning a work file out of your personal OneDrive",task:"Remove Lakeside Staff Schedule - copy.xlsx from your personal OneDrive.",steps:[{move:"Check that the original is in your work OneDrive or the team library.",why:"You are deleting a copy, not the only copy. Confirm the real file is safe first."},{move:"In your personal OneDrive, select the file and select Delete, then confirm.",why:"Delete moves it to the personal Recycle bin, where it would still sit for 30 days."},{move:"Open the Recycle bin, select the file, and select Delete again to delete it permanently.",why:"The goal is no copy in personal storage. Permanently deleting it from the Recycle bin finishes the job."},{move:"Tell your supervisor if the file had patient information in it.",why:"Medical offices have a process for possible privacy problems. Reporting it is part of fixing it."}],result:"The work file exists only in the work account.",takeaway:"One work file, in one work location. Copies in personal storage are risks, not backups."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"In File Explorer you see two OneDrive folders: OneDrive - Personal and OneDrive - Lakeside Medical Associates. Where should you save the new appointment reminder template you made for work?",options:["OneDrive - Personal","OneDrive - Lakeside Medical Associates","Either one; they sync to the same place","The Desktop, so it is easy to find"],correctIndex:1,explanation:"The folder named for your organization is your work OneDrive. Work files go there.",optionRationales:["That is your personal account. Work files don't belong there.","Correct. The organization's name marks your work OneDrive.","They are two separate accounts that sync to two separate places.","The desktop isn't backed up to the cloud unless your organization set that up. Save work files in the work OneDrive."]},{type:"knowledge-check",question:"How long does a personal OneDrive keep a file you delete before it is removed for good?",options:["7 days","30 days","93 days","Forever"],correctIndex:1,explanation:"Personal accounts keep deleted files in the Recycle bin for 30 days. Work or school accounts keep them 93 days unless the organization changed that.",optionRationales:["It is longer than a week.","Correct. Personal OneDrive keeps deleted items for 30 days.","93 days is the usual setting for work or school accounts.","Deleted items are removed after the retention period."]}]}],challenge:[{type:"paragraph",text:"Compare the two kinds of accounts."},{type:"list",ordered:!0,items:["Sign in to OneDrive with your school account. Write down the web address in the browser's address bar and the name of the button at the top of the left pane.","If you have a personal Microsoft account, sign in to it at home or on your own device (not on a shared computer) and write down the same two things. If you don't have one, use the table in this lesson.","Write three sentences: one file type that belongs only in the work account, one that belongs only in a personal account, and what you would do if you found a work file in a personal account."]},{type:"callout",variant:"success",text:"Deliverable: Submit your notes and three sentences to your instructor or course folder."}]}],g=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/onedrive/module-2/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),h=[{slug:"uploading-and-creating",title:"Uploading Files and Creating Folders",description:"Build a folder structure that makes sense to your team, upload files and whole folders, create new Office files in OneDrive, and name them so anyone can find them.",objectives:["Create folders in My files and inside other folders","Upload one or several files, and upload a whole folder","Create a new Word, Excel, or PowerPoint file directly in OneDrive","Name files and folders clearly and avoid characters OneDrive doesn't allow"],duration:"15 min",slides:g("uploading-and-creating",["Create or upload: one button for folders, new files, and uploads","Plan folders by the work, not by the person","Files upload versus Folder upload","New Office files start as Document, Book, or Presentation: rename them","Names people can find: clear words, no forbidden characters"]),sections:[{heading:"A place for everything",blocks:[{type:"scenario",role:"You track patient referrals at Lakeside Medical Associates.",text:"Referral paperwork lives in three places right now: an email folder, a USB drive, and a printout on Maria's desk. Maria asks you to set up a Referrals folder in OneDrive, put the tracking log and fax cover sheet in it, start a phone log, and upload the Health Fair materials a volunteer gave you on a flash drive.",task:"Create the folder, upload files and a folder, and start a new document, with names the whole team will understand."},{type:"paragraph",text:"In OneDrive on the web, everything new starts from one button. In a work or school OneDrive it is Create or upload; in a personal OneDrive it is Add new. It creates a folder, a new Word document, Excel workbook, or PowerPoint presentation, or uploads files or a whole folder from your computer. Whatever you create goes into the folder you have open, so open the right folder first."},{type:"table",caption:"The Create or upload menu",columns:["Choice","What it does"],rows:[["Folder","Asks for a folder name, then creates the folder where you are"],["Word document, Excel workbook, PowerPoint presentation","Creates a blank file and opens it in the web app. It starts with a name like Document or Book, so rename it"],["Files upload","Opens your computer's file picker. Hold Ctrl to pick several files"],["Folder upload","Uploads a whole folder, with everything inside it, in one step"]]},{type:"callout",variant:"version",text:"Microsoft is moving Create or upload from the top of the left pane to the right side of the page, near the command bar. Same button, same choices, new spot."}]},{heading:"Folders that make sense to everyone",blocks:[{type:"paragraph",text:"Organize by the work, not by the person. A folder called Referrals tells everyone what is inside; a folder called Alex's Stuff tells no one anything. Keep the structure shallow: two or three levels is easier to navigate than seven. And put a file in one folder only. Two copies in two folders means two versions, and soon nobody knows which one is current."},{type:"drag-drop",mode:"sort",title:"Good name or bad name?",prompt:"Sort each file name. A good name says what the file is and works in OneDrive.",buckets:[{id:"good",label:"Clear name"},{id:"bad",label:"Rename it"}],items:[{id:"a",text:"Referral Tracking Log.xlsx",bucket:"good"},{id:"b",text:"scan0042.pdf",bucket:"bad"},{id:"c",text:"Flu Clinic Flyer.docx",bucket:"good"},{id:"d",text:"Document (3).docx",bucket:"bad"},{id:"e",text:"Fax: Riverside?.docx",bucket:"bad"},{id:"f",text:"Insurance Verification Checklist.docx",bucket:"good"}],explanation:"A name should tell a coworker what the file is without opening it. OneDrive doesn't allow these characters in names: \" * : < > ? / \\ | so a name with a colon or question mark has to change."},{type:"callout",variant:"info",text:"Characters OneDrive doesn't allow in file or folder names: \" * : < > ? / \\ |. Some names aren't allowed at all, such as .lock, CON, PRN, AUX, NUL, desktop.ini, and any name that contains _vti_ or starts with ~$. A single file can be up to 250 GB."}]},{heading:"Uploading",blocks:[{type:"worked-example",title:"Uploading two referral files into the new folder",task:"Put Referral Tracking Log.xlsx and Referral Fax Cover Sheet.docx from your computer into the Referrals folder.",steps:[{move:"Open the Referrals folder first.",why:"Uploads land in the folder you have open. Uploading from My files and moving later is extra work."},{move:"Select Create or upload, then Files upload.",why:"Files upload opens your computer's file picker, the same Open window you use everywhere in Windows."},{move:"Click the first file, hold Ctrl, click the second, then select Open.",why:"Ctrl+click picks several files at once, so both upload in one step."},{move:"Watch for the upload message, then check that both files are in the list.",why:"Confirming takes a second and catches a file that was skipped or picked by mistake."}],result:"Both files are in OneDrive, in the folder where the team will look for them.",takeaway:"Open the destination first, then upload. Use Folder upload when you have a whole folder to bring in."},{type:"drag-drop",mode:"order",title:"Put the upload steps in order",prompt:"Drag the steps into the right order for uploading a file into a folder.",items:[{id:"1",text:"Open the folder where the file belongs"},{id:"2",text:"Select Create or upload"},{id:"3",text:"Select Files upload"},{id:"4",text:"Pick the file on your computer and select Open"},{id:"5",text:"Check that the file appears in the folder"}]},{type:"tip",text:"On a work computer with the OneDrive sync app, you can also save straight into OneDrive from Word or Excel, or drag files into the OneDrive folder in File Explorer. Module 5 covers the sync app."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You select Create or upload › Word document in the Referrals folder. What should you do next?",options:["Nothing; OneDrive names it for you","Rename it from Document to a name that says what it is","Download it so it is saved","Move it to My files so it is easier to find"],correctIndex:1,explanation:"New files start with a generic name like Document. Give it a clear name right away so nobody ends up with Document (1), Document (2), and Document (3).",optionRationales:["OneDrive gives it a generic name like Document. That name won't help anyone find it.","Correct. Rename it right away with a clear name.","Files in OneDrive are saved in the cloud already. Downloading makes an extra copy.","It is already where it belongs, in the Referrals folder."]},{type:"knowledge-check",question:"Which file name will OneDrive refuse?",options:["Referral Log - Riverside.xlsx","Referral Log (Riverside).xlsx","Referral Log: Riverside.xlsx","Referral_Log_Riverside.xlsx"],correctIndex:2,explanation:"A colon (:) is one of the characters OneDrive doesn't allow, along with \" * < > ? / \\ |. Hyphens, parentheses, and underscores are fine.",optionRationales:["Hyphens are allowed.","Parentheses are allowed.","Correct. A colon isn't allowed in OneDrive file names.","Underscores are allowed."]}]}],challenge:[{type:"paragraph",text:"Organize a small set of your own practice files in your real OneDrive."},{type:"list",ordered:!0,items:["Sign in at onedrive.com with your school account.","In My files, create a folder named OneDrive Practice.","Open it and upload two files from the computer (any class files, never patient information).","Create a new Word document in the folder and rename it Practice Notes.","Type one sentence in Practice Notes describing how you named your files and why."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of the OneDrive Practice folder showing all three files to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"moving-copying-renaming",title:"Moving, Copying, Renaming, and Deleting",description:"Keep OneDrive tidy: rename unclear files, move files into the right folder, copy templates, and delete what you don't need, without losing anything.",objectives:["Rename a file or folder","Move one or several files with Move to or by dragging","Copy a file to another folder with Copy to","Delete files and know they go to the Recycle bin"],duration:"15 min",slides:g("moving-copying-renaming",["Rename, Move to, Copy to, Delete: four commands that keep OneDrive tidy","Move keeps one file; Copy makes a second, separate file","Select several files with the check boxes or Ctrl+click","Moving a shared file keeps its sharing","Delete sends files to the Recycle bin"]),sections:[{heading:"Clean up before it gets out of hand",blocks:[{type:"scenario",role:"You are tidying the front desk's OneDrive after a busy week.",text:"My files has a scanned invoice called scan0042.pdf, three patient forms that should be in Patient Forms, a Copy of Flu Clinic Flyer nobody needs, and a supply log with no folder. Tasha needs the reminder template for her training packet, but the original must stay with the front desk files.",task:"Rename, move, copy, and delete so every file has a clear name and one home."},{type:"table",caption:"Four commands, and when to use each",columns:["Command","What happens","Use it when"],rows:[["Rename","The same file gets a new name","The name doesn't say what the file is"],["Move to","The same file goes to a new folder","A file is in the wrong place"],["Copy to","A second, separate file is created in another folder","You need a starting point for something new (a template)"],["Delete","The file goes to the Recycle bin","A file is a duplicate or no longer needed"]]},{type:"paragraph",text:"Select a file and these commands appear in the command bar. You can also right-click the file or select More actions (…) next to its name. To work on several files at once, select their round check boxes (or hold Ctrl and click each row), then choose the command once."}]},{heading:"Move or copy?",blocks:[{type:"paragraph",text:"Moving keeps one file; it just lives somewhere else. Its sharing, version history, and comments go with it. Copying makes a brand-new file with its own history. The copy is not shared with anyone, and changes to one don't change the other. That is exactly what you want for a template and exactly what you don't want for a schedule, where a copy quickly becomes the wrong version."},{type:"drag-drop",mode:"sort",title:"Move it or copy it?",prompt:"Sort each situation.",buckets:[{id:"move",label:"Move to"},{id:"copy",label:"Copy to"}],items:[{id:"a",text:"A form was saved in My files instead of Patient Forms",bucket:"move"},{id:"b",text:"Tasha needs her own copy of the reminder template to customize",bucket:"copy"},{id:"c",text:"The supply log belongs in the new Supplies folder",bucket:"move"},{id:"d",text:"You want to start next month's flyer from this month's",bucket:"copy"},{id:"e",text:"The staff schedule is in the wrong folder and the team edits it daily",bucket:"move"}],explanation:"If the same file should simply live somewhere else, move it. If you need a separate starting point that will change on its own, copy it."},{type:"worked-example",title:"Moving three forms in one step",task:"Move Medical Records Release Form, Financial Policy Form, and Telehealth Consent Form from My files into Patient Forms.",steps:[{move:"Select the round check box on each of the three rows.",why:"Selecting all three first means one Move instead of three."},{move:"Select Move to in the command bar.",why:"Move to opens a panel where you choose a destination folder, which is more precise than dragging in a long list."},{move:"Select Patient Forms in the panel, then Move here.",why:"Move here puts the files inside the folder you opened in the panel."},{move:"Open Patient Forms to confirm.",why:"A quick look confirms all three arrived."}],result:"All three forms are in Patient Forms, and My files is shorter.",takeaway:"Select everything first, then act once. You can also drag selected files onto a folder in the list."}]},{heading:"Deleting safely",blocks:[{type:"paragraph",text:"Delete sends a file to the OneDrive Recycle bin, not straight into oblivion. In a work or school account it stays there for 93 days unless your organization changed that; in a personal account, 30 days. Module 4 shows how to restore deleted files. Before you delete a file someone else might use, check the Sharing column or the details pane. If it is shared, ask first."},{type:"callout",variant:"warning",text:"You can only delete files you own or can edit. Files shared with you belong to their owner. If something shared with you is no longer needed, ask the owner, or remove it from your Shared list instead of trying to delete it."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You move a shared staff schedule from My files into the Front Desk folder. What happens to the people it was shared with?",options:["They lose access and you must share it again","They keep access; moving keeps the same file and its sharing","They get a new copy of the file","They are notified and must accept the move"],correctIndex:1,explanation:"Moving keeps the same file, so its sharing, version history, and comments move with it.",optionRationales:["Moving within your OneDrive keeps the file's sharing.","Correct. It is the same file in a new folder.","Copying makes a new file. Moving does not.","No one has to accept anything when you move your own file."]},{type:"knowledge-check",question:"Tasha wants to customize the appointment reminder template for her training packet without changing the front desk version. What should you do?",options:["Move the template to her folder","Copy the template to her folder","Rename the template","Share the template with Can edit"],correctIndex:1,explanation:"Copy to makes a separate file. Tasha can change her copy and the original stays as it is.",optionRationales:["Moving would take the template away from the front desk.","Correct. A copy is a separate file she can change freely.","Renaming doesn't give her a separate file.","Sharing with Can edit lets her change the original, which is what you want to avoid."]}]}],challenge:[{type:"paragraph",text:"Use the OneDrive Practice folder from the previous lesson (or create it now) in your real OneDrive."},{type:"list",ordered:!0,items:["Create a folder named Archive inside OneDrive Practice.","Rename one of your practice files so the name says exactly what it is.","Copy Practice Notes into Archive with Copy to. Open both copies and change one word in the copy. Confirm the original didn't change.","Move one practice file into Archive with Move to (or by dragging it onto the folder).","Delete the copied Practice Notes in Archive, then open the Recycle bin and confirm it is there."]},{type:"callout",variant:"success",text:"Deliverable: Submit screenshots of the OneDrive Practice folder, the Archive folder, and the Recycle bin to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"finding-files",title:"Finding Files: Search, Favorites, and Shortcuts",description:"Find any file in seconds with Search, Home, Shared, and the People and Meetings views, keep the files you use every day in Favorites, and add shortcuts to shared folders.",objectives:["Search OneDrive by file name","Add files to Favorites and open them from the Favorites view","Find files others shared with you in Shared, People, and Meetings","Add a shortcut to a shared folder to My files, and remove it"],duration:"15 min",slides:g("finding-files",["Four ways to find a file: Search, Home, Shared, and Browse files by","Favorites: the files you use every day, one click away","Shared with you: files that live in someone else's OneDrive","Add shortcut to My files for a shared folder you use often"]),sections:[{heading:"Stop clicking through folders",blocks:[{type:"scenario",role:"You start every shift at the Lakeside check-in desk.",text:"Every morning you open the same three files: the New Patient Intake Form, the Office Phone List, and the Front Desk Procedures folder that Maria shares with the team. Every morning you click through folders to reach them, while patients wait.",task:"Set up OneDrive so your everyday files are one click away, and learn the fastest way to find anything else."},{type:"table",caption:"Where to look, depending on what you remember",columns:["You remember…","Look in"],rows:[["Part of the name","Search (type it and press Enter)"],["You opened it recently","Home"],["Someone sent it to you","Shared › Shared with you"],["Who you worked on it with","People"],["It came up in a Teams meeting","Meetings"],["You use it all the time","Favorites"]]}]},{heading:"Favorites and shortcuts",blocks:[{type:"paragraph",text:"In a work or school OneDrive, Add to favorites (right-click a file, or select More actions) puts a file in the Favorites view. Favorites doesn't move or copy the file; it is a bookmark. Remove from favorites takes the bookmark away."},{type:"paragraph",text:"Files shared with you stay in their owner's OneDrive, so they are not in your My files. For a shared folder you use every day, select it in Shared and choose Add shortcut to My files. The shortcut appears in My files (and in File Explorer, if you use the sync app), but the folder still belongs to its owner, and their sharing still decides what you can do. Shortcuts work for folders, not single files. To remove one, select it in My files and choose Remove shortcut from My files; that doesn't affect the owner's folder."},{type:"drag-drop",mode:"match",title:"Match the tool to the job",prompt:"Drag each job onto the OneDrive tool that does it.",items:[{id:"fav",text:"Add to favorites",match:"Keep a file you open daily one click away"},{id:"sc",text:"Add shortcut to My files",match:"Put a folder someone shared with you in your My files"},{id:"search",text:"Search",match:"Find a file when you remember part of its name"},{id:"people",text:"People",match:"Find files you share with one coworker"},{id:"home",text:"Home",match:"Reopen something you edited this morning"}]},{type:"callout",variant:"info",text:"Search looks through your OneDrive and the files shared with you. If you get too many results, add another word from the file's name."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Maria shared the Front Desk Procedures folder with you, and you want it in My files. What happens when you select Add shortcut to My files?",options:["A copy of the folder is saved in your OneDrive","The folder moves from Maria's OneDrive to yours","A shortcut to Maria's folder appears in My files; the folder stays hers","Maria gets ownership of your My files"],correctIndex:2,explanation:"A shortcut points to the shared folder. It still lives in Maria's OneDrive and her sharing settings still apply.",optionRationales:["No copy is made, so there is still only one version.","Nothing moves. The folder stays in Maria's OneDrive.","Correct. You get a shortcut; the folder stays where it is.","Shortcuts don't change ownership of anything."]},{type:"knowledge-check",question:"You remove a file from Favorites. What happens to the file?",options:["It is deleted","It moves to the Recycle bin","Nothing; only the bookmark is removed","It is unshared"],correctIndex:2,explanation:"Favorites is a list of bookmarks. Removing a favorite leaves the file exactly where it was.",optionRationales:["Favorites never deletes files.","Only Delete sends a file to the Recycle bin.","Correct. The file is unchanged.","Sharing isn't affected by Favorites."]}]}],challenge:[{type:"paragraph",text:"Set up your real OneDrive for speed."},{type:"list",ordered:!0,items:["Sign in at onedrive.com with your school account.","Search for one of your practice files by typing part of its name.","Add two files you use often to Favorites, then open the Favorites view.","If anyone has shared a folder with you, open Shared, select it, and choose Add shortcut to My files. (If nothing is shared with you, skip this step.)","Write two sentences: which way of finding files you will use most, and why."]},{type:"callout",variant:"success",text:"Deliverable: Submit a screenshot of your Favorites view and your two sentences to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]}],i="/images/ms-office/onedrive/module-3",j=(a,b)=>b.map((b,c)=>({src:`${i}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),k=[{slug:"sharing-with-the-right-permission",title:"Sharing Files with the Right Permission",description:"Share a file by sending it to specific people or by copying a link, choose who the link works for and what it allows, and share patient information the safe way.",objectives:["Share a file with specific people with Can edit, Can view, or Can review","Copy a link and choose who it works for: Anyone, People in your organization, People with existing access, or People you choose","Add an expiration date or password to a link where your organization allows it","Share patient information only with named people, view-only unless editing is needed, and never with an Anyone link"],duration:"20 min",slides:j("sharing-with-the-right-permission",["Two ways to share: send to people, or copy a link","Permissions: Can edit, Can view, Can review, Can't download","Link settings: who the link works for","Expiration dates and passwords","Sharing patient information: named people, least access, never Anyone","Quick check: pick the right link"]),sections:[{heading:"Three requests, three different answers",blocks:[{type:"scenario",role:"You handle file requests at the Lakeside front desk.",text:"Before lunch, Maria wants to edit the flu clinic flyer, Kevin in billing needs to look at (not change) the November staff schedule, the whole office needs the phone list, and Riverside Imaging's scheduler needs a patient's referral packet. Attaching four files to four emails would create four copies. Sharing from OneDrive gives each person the right access to the one real file.",task:"Share each file with exactly the access each person needs, and handle the patient file safely."},{type:"paragraph",text:"Select a file and select Share (in the command bar, or by right-clicking the file). The Share window has two parts. At the top, you share with specific people: type their names or email addresses in Add a name, group, or email, choose a permission with the permission button next to the box, add a message if you like, and select Send. They get an email with a link to the file. At the bottom, Copy link makes a link you can paste into an email, a Teams chat, or a document. The gear next to Copy link opens Link settings, where you choose who the link works for."}]},{heading:"What people can do: permissions",blocks:[{type:"table",caption:"Permissions in OneDrive",columns:["Permission","They can","Use it for"],rows:[["Can edit","Make any changes, and share the file further","Coworkers who work on the file with you"],["Can view","Open and read it, but not change it","People who only need to read: most outside offices"],["Can review","View, comment, and suggest changes (Word documents only)","A manager reviewing your draft"],["Can't download","View, but not download a copy (work or school accounts only)","Sensitive files people should read but not keep"]]},{type:"callout",variant:"info",text:"Start with the least access that gets the job done. You can always give more access later. Taking access back after someone downloaded a copy doesn't take the copy back."}]},{heading:"Who a link works for: link settings",blocks:[{type:"table",caption:"Link settings › Share the link with",columns:["Option","Who can open the link","At Lakeside"],rows:[["Anyone","Anyone who has the link, including people outside the organization. No sign-in needed","Only for public material, like the flu clinic flyer. Never for patient information"],["People in Lakeside Medical Associates","Anyone signed in with a Lakeside account","Internal files the whole office may read"],["People with existing access","Only people who already have access. It doesn't change anyone's permissions","Pointing a coworker to a file they can already open"],["People you choose","Only the names or emails you enter","Anything sensitive, including patient files"]]},{type:"paragraph",text:"Under More settings you choose the link's permission (Can edit, Can view, and so on). For links that work for Anyone, you can also set an expiration date (the link stops working after it) and a password (people must type it to open the file). In a personal OneDrive these two options need a Microsoft 365 subscription. In a work or school account, your organization decides which options you can use: a choice that is greyed out was turned off by your administrators. Select Apply, then Copy."},{type:"drag-drop",mode:"sort",title:"Pick the right link",prompt:"Drag each situation to the link setting that fits it best.",buckets:[{id:"anyone",label:"Anyone (view only, with an expiration date)"},{id:"org",label:"People in Lakeside Medical Associates"},{id:"choose",label:"People you choose"},{id:"existing",label:"People with existing access"}],items:[{id:"a",text:"The public flu clinic flyer for a community partner's website",bucket:"anyone"},{id:"b",text:"The office phone list every Lakeside employee may read",bucket:"org"},{id:"c",text:"A patient's referral packet for one scheduler at Riverside Imaging",bucket:"choose"},{id:"d",text:"Reminding Maria where a file is that she can already edit",bucket:"existing"},{id:"e",text:"A billing report only Kevin and Dr. Shah should see",bucket:"choose"}],explanation:"Match the link to the smallest group that needs the file. Anyone links are for public material only. Patient information always goes to people you choose."},{type:"image",src:`${i}/sharing-with-the-right-permission/infographic.png`,alt:"Quick reference: the four link options, the four permissions, and the rules for sharing patient information",caption:"Quick reference: sharing with the right permission."}]},{heading:"Sharing patient information safely",blocks:[{type:"worked-example",title:"Sending a referral packet to Riverside Imaging",task:"Riverside Imaging's scheduler needs to read the referral packet for an upcoming patient appointment.",steps:[{move:"Confirm Lakeside shares with Riverside Imaging this way.",why:"Practices share patient information with outside organizations only under agreements and processes they have approved. If you aren't sure, ask your supervisor before sharing."},{move:"Select the packet and select Share. Type scheduling@riversideimaging.example.",why:"Sharing with the named person means only that person can open the file. OneDrive warns you that the address is outside your organization, which is your cue to double-check it."},{move:"Set the permission to Can view.",why:"The scheduler needs to read the packet, not change it. Least access is the rule for patient information."},{move:"Add a short message and select Send.",why:"The message tells them what it is without repeating any patient details in the email."},{move:"Never switch to an Anyone link to save time.",why:"An Anyone link opens for whoever has it. It can be forwarded, pasted in the wrong chat, or seen over a shoulder."}],result:"One person, view-only access, to one file, and an email that contains no patient details.",takeaway:"For patient information: named people, the least access that works, and never an Anyone link."},{type:"callout",variant:"warning",text:"If you share patient information with the wrong person or the wrong kind of link, remove the access right away (the next lesson shows how) and tell your supervisor. Reporting quickly is part of fixing it."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Kevin needs to read the November staff schedule but shouldn't change it. What do you choose?",options:["Share with Kevin, Can edit","Share with Kevin, Can view","Copy an Anyone link","Email Kevin a downloaded copy"],correctIndex:1,explanation:"Can view lets Kevin open and read the one real schedule, which stays current, without being able to change it.",optionRationales:["Can edit gives Kevin more access than he needs.","Correct. View-only access to the real file.","An Anyone link works for anyone who gets it. The staff schedule is internal.","A downloaded copy goes out of date the next time the schedule changes."]},{type:"knowledge-check",question:"Which Share option is never right for a patient's records?",options:["People you choose, with Can view","Sharing with a named person, Can view","Anyone","People with existing access"],correctIndex:2,explanation:"An Anyone link works for whoever has it, with no sign-in. Patient information is shared only with named people.",optionRationales:["People you choose limits the link to named people. That fits patient information.","Sharing with a named person with view-only access is the safe pattern.","Correct. Never use an Anyone link for patient information.","This only works for people who already have access, so it doesn't expose the file to anyone new."]}]}],challenge:[{type:"paragraph",text:"Share a practice file in your real OneDrive (never a file with personal or patient information). Work with a classmate."},{type:"list",ordered:!0,items:["Sign in at onedrive.com with your school account and open your OneDrive Practice folder (create it if you don't have it).","Select Practice Notes and select Share. Type your classmate's school email address, set the permission to Can view, and type a short message.","Before you select Send, take a screenshot of the Share window showing the person and the permission. Then send it.","Open the Share window again and select the gear next to Copy link. Write down which Share the link with options your school allows and which are greyed out.","Ask your classmate to confirm they can open the file but not edit it."]},{type:"callout",variant:"success",text:"Deliverable: Submit your screenshot and your list of available link options to your instructor or course folder. If you cannot sign in or don't have a partner, submit this lesson's practice simulation results page instead."}]},{slug:"managing-access",title:"Managing Access and Stopping Sharing",description:"See who has access to your files, change what they can do, remove a person or a link, and stop sharing a file completely.",objectives:["Find the files you have shared with Shared › Shared by you","Open Manage access and read its People, Groups, and Links tabs","Change a person's permission and remove their direct access","Remove a sharing link and stop sharing a file entirely"],duration:"15 min",slides:j("managing-access",["Sharing isn't one-and-done: review it","Three ways to open Manage access","People, Groups, and Links","Change, remove, or stop sharing","When to review sharing"]),sections:[{heading:"Sharing needs upkeep",blocks:[{type:"scenario",role:"Maria asked you to clean up sharing on the front desk's files.",text:"A temporary receptionist finished her assignment last week but can still edit the holiday coverage plan. Kevin can edit a plan he should only read. Somebody created an Anyone link to the staff schedule. And the supply vendor whose contract ended still has access to the supply order log.",task:"Find every shared file, fix each person's access, remove the risky link, and stop sharing where nobody outside should have access."},{type:"paragraph",text:"Start in Shared › Shared by you. It lists your files that other people can open. Then open Manage access for a file in any of these ways: right-click the file and select Manage access; select the file, open the details pane with the information (i) button, and select Manage access; or select the people pictures at the bottom of the Share window."}]},{heading:"Inside Manage access",blocks:[{type:"table",caption:"The Manage access panel",columns:["Part","What it shows or does"],rows:[["People tab","Everyone with access, and their permission. Select a person's permission to change it to Can edit or Can view, or choose Remove direct access"],["Groups tab","Groups (such as a team) that have access"],["Links tab","Every sharing link for the file, who it works for, and what it allows. Remove link deletes one"],["Grant access","Opens the Share window to give someone access"],["Stop sharing","Removes everyone's access and every link. You keep access"]]},{type:"callout",variant:"info",text:"You can't change a link from edit to view. Remove the link, then create a new one with the permission you want. Anyone who had the old link loses access when you remove it."},{type:"drag-drop",mode:"match",title:"Match the fix to the problem",prompt:"Drag each fix onto the problem it solves.",items:[{id:"a",text:"A coworker can edit a file they should only read",match:"Change their permission to Can view"},{id:"b",text:"A temp's assignment ended",match:"Remove direct access"},{id:"c",text:"An Anyone link exists for an internal file",match:"Remove the link on the Links tab"},{id:"d",text:"No one outside you should have the file anymore",match:"Stop sharing"}]}]},{heading:"When to review",blocks:[{type:"list",items:["When someone leaves the team or changes roles","When a project or a contract with an outside company ends","Whenever you notice an Anyone link on a file that isn't public","On a regular schedule your office sets for sensitive files"]},{type:"worked-example",title:"Removing a temp's access",task:"Jen Cole's temporary assignment ended. Remove her access to the Holiday Coverage Plan.",steps:[{move:"Right-click Holiday Coverage Plan and select Manage access.",why:"Manage access is the one place that lists everyone and every link for the file."},{move:"On the People tab, select Jen Cole's permission (Can edit).",why:"The menu has the permissions and Remove direct access."},{move:"Select Remove direct access, then Remove to confirm.",why:"Jen loses access right away. Everyone else keeps theirs."},{move:"Check the Links tab for links that might still include her.",why:"A person can have access through a link as well as directly."}],result:"Only current staff can open the plan.",takeaway:"Removing access is part of sharing. Do it as soon as someone's need ends."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You shared a file with an edit link and now want people to only view it. What should you do?",options:["Change the link's permission to Can view","Remove the edit link and create a new view-only link","Rename the file","Move the file to another folder"],correctIndex:1,explanation:"A link's permission can't be switched. Remove it and create a new link with Can view.",optionRationales:["A link can't be switched between edit and view.","Correct. Remove the link, then make a new one.","Renaming doesn't change who has access.","Moving the file keeps its links and sharing."]},{type:"knowledge-check",question:"What does Stop sharing do?",options:["Deletes the file","Removes everyone's access and every link, but you keep access","Removes only links that work for Anyone","Makes the file read-only for everyone"],correctIndex:1,explanation:"Stop sharing takes away all direct access and all links. The file stays in your OneDrive and you keep access.",optionRationales:["The file isn't deleted.","Correct.","It removes all links and all direct access, not only Anyone links.","It removes access instead of changing it to read-only."]}]}],challenge:[{type:"paragraph",text:"Clean up the sharing from the previous lesson's challenge in your real OneDrive."},{type:"list",ordered:!0,items:["Sign in at onedrive.com and open Shared › Shared by you. Take a screenshot.","Open Manage access for Practice Notes. Change your classmate's permission from Can view to Can edit, and take a screenshot.","Remove your classmate's direct access (or select Stop sharing). Take a screenshot of Manage access showing that only you have access.","If you created a link, remove it on the Links tab."]},{type:"callout",variant:"success",text:"Deliverable: Submit your three screenshots to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"co-authoring-and-comments",title:"Co-authoring and Comments",description:"Edit a document at the same time as your coworkers, see who is working where, and use comments, @mentions, and Reviewing mode instead of email back-and-forth.",objectives:["Open a shared document in Word for the web and recognize co-authors' presence","Add a comment to a paragraph and @mention a coworker","Reply to and resolve comment threads","Switch between Editing, Reviewing, and Viewing modes"],duration:"15 min",slides:j("co-authoring-and-comments",["Co-authoring: everyone in the one real file","Presence: see who is editing where","Comments and @mentions","Reply, then resolve","Editing, Reviewing, and Viewing modes"]),sections:[{heading:"One file, many editors",blocks:[{type:"scenario",role:"You are updating the Check-In Procedures with the front desk team.",text:"In the past, updating the procedures meant emailing a document around, collecting three edited copies, and spending an afternoon combining them. Now the document is in OneDrive, shared with the team. Maria is editing the insurance section right now, Kevin left a question in a comment, and Tasha finished her part.",task:"Work in the same document at the same time, answer comments, and pull Maria into a question without leaving the file."},{type:"paragraph",text:"When a Word, Excel, or PowerPoint file is in OneDrive and shared with edit permission, several people can work in it at the same time. This is co-authoring. Each person's changes show up for the others within moments, and colored flags show who is working where. Word for the web saves as you type, so nobody needs to save and send a new copy."},{type:"key-terms",terms:[{term:"Co-authoring",definition:"Several people editing the same file at the same time."},{term:"Presence",definition:"The pictures at the top and the colored flags in the document that show who is in the file and where."},{term:"Comment",definition:"A note attached to a paragraph, outside the text, that people can reply to."},{term:"@mention",definition:"Typing @ and a name in a comment, so that person gets a notification."},{term:"Resolve",definition:"Marking a comment thread as done. It stays in the document's history but leaves the active list."}]}]},{heading:"Comments and @mentions",blocks:[{type:"list",ordered:!0,items:["Click in the paragraph you want to comment on.","Select Review › New comment (or right-click the paragraph and select New comment).","Type your comment. To get someone's attention, type @ and the first letters of their name, then pick them from the list.","Post the comment. A mentioned coworker gets a notification with a link to the comment.","To answer a comment, type in its Reply box. When the question is settled, open the thread's More thread actions (…) and select Resolve thread."]},{type:"tip",text:"Comment instead of rewriting someone else's section. A comment asks; an edit decides. For changes you want the owner to approve, switch to Reviewing mode so your edits show as suggestions they can accept or reject."},{type:"drag-drop",mode:"order",title:"Order the comment workflow",prompt:"Put these steps in the order they happen.",items:[{id:"1",text:"Click in the paragraph"},{id:"2",text:"Select Review › New comment"},{id:"3",text:"Type the comment and @mention a coworker"},{id:"4",text:"The coworker replies"},{id:"5",text:"Resolve the thread"}]}]},{heading:"Editing, Reviewing, and Viewing",blocks:[{type:"table",caption:"Modes in Word for the web (the mode button near the top right)",columns:["Mode","What it does","Use it when"],rows:[["Editing","Your changes go straight into the document","It is your section, or you were asked to edit"],["Reviewing","Your changes show as suggestions others can accept or reject","You are suggesting changes to someone else's work"],["Viewing","You can read the document but not change the text","You only want to read without changing anything by accident"]]},{type:"callout",variant:"info",text:"Version history (Module 4) keeps earlier versions of shared files, so a co-author's mistake can be undone. Co-authors should still agree on who edits which section."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You want Maria to answer a question about the insurance section without leaving the document. What is the best way?",options:["Email her a screenshot","Add a comment on that paragraph and @mention Maria","Type the question into the paragraph in capital letters","Make a copy of the document for her"],correctIndex:1,explanation:"An @mention in a comment notifies Maria and keeps the question attached to the exact paragraph.",optionRationales:["Email separates the question from the document and adds back-and-forth.","Correct.","Typing questions into the text clutters the document and someone has to remove them later.","A copy defeats co-authoring. Everyone should work in the one file."]},{type:"knowledge-check",question:"You want to suggest wording changes to Kevin's section without changing it directly. Which mode do you use?",options:["Editing","Reviewing","Viewing","None; email him instead"],correctIndex:1,explanation:"Reviewing mode records your edits as suggestions Kevin can accept or reject.",optionRationales:["Editing changes the text directly.","Correct.","Viewing doesn't let you change text at all.","Suggestions in the document are clearer than an email describing them."]}]}],challenge:[{type:"paragraph",text:"Co-author with a classmate in your real OneDrive."},{type:"list",ordered:!0,items:["Share Practice Notes with your classmate with Can edit (or have them share a file with you).","Both of you open the file in Word for the web at the same time. Take a screenshot showing your classmate's picture or flag in the document.","Add a comment on one paragraph that @mentions your classmate with a question. Have them reply, then resolve the thread.","Switch to Reviewing mode, change one word, and have your classmate accept or reject the suggestion."]},{type:"callout",variant:"success",text:"Deliverable: Submit your screenshot of co-authoring and a screenshot of the resolved comment to your instructor or course folder. If you cannot sign in or don't have a partner, submit this lesson's practice simulation results page instead."}]}],l="/images/ms-office/onedrive/module-4",m=(a,b)=>b.map((b,c)=>({src:`${l}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),n=[{slug:"version-history",title:"Restoring an Earlier Version",description:"Use version history to see earlier versions of a file, check what changed, and restore the right one, from OneDrive on the web or from inside Word.",objectives:["Open version history from OneDrive on the web and from a Word document","Open an earlier version to check it before restoring","Restore an earlier version and explain what happens to the current one","Explain how long versions are kept in personal and work or school accounts"],duration:"15 min",slides:m("version-history",["Version history: every save is a step you can go back to","Three ways to open version history","Check the version before you restore it","Restoring doesn't erase anything","How long versions are kept"]),sections:[{heading:"Someone typed over the schedule",blocks:[{type:"scenario",role:"You keep the staff schedule up to date at Lakeside.",text:"At 9:05 this morning, Kevin pasted October's shifts over the November staff schedule by mistake and saved. Half the office is looking at the wrong shifts. Nobody made a backup copy, and nobody needs to: OneDrive kept the earlier versions.",task:"Find yesterday's correct version, check it, and restore it, without losing anything."},{type:"paragraph",text:"Version history is a list of earlier versions of a file that OneDrive keeps as people change it. Each version shows when it was saved and who saved it. You can open an earlier version to read it, and restore it to make it the current version again."},{type:"table",caption:"Three ways to open version history",columns:["From","Steps"],rows:[["OneDrive on the web","Right-click the file (or select it and select More actions …) › Version history"],["File Explorer (with the sync app)","Right-click the file in your OneDrive folder › Version history"],["Word, Excel, or PowerPoint (desktop)","Select the file name in the title bar › Version History, or File › Info › Version History"]]}]},{heading:"Check, then restore",blocks:[{type:"worked-example",title:"Restoring yesterday's staff schedule",task:"Put back the version of Staff Schedule - November.xlsx that Maria saved yesterday afternoon.",steps:[{move:"Right-click Staff Schedule - November.xlsx and select Version history.",why:"The Version history panel lists every saved version with the date, time, and person."},{move:"Find the version Maria saved yesterday, before Kevin's change this morning.",why:"The Modified and Modified by columns tell you which version is the last good one."},{move:"Open that version and read it before you restore it.",why:"Opening it first lets you confirm it really has the November shifts. Restoring the wrong version just creates a new problem."},{move:"Select the ellipses (…) next to that version and select Restore.",why:"Restore makes that version the current version again. Kevin's version stays in the list, so nothing is lost."},{move:"Tell the team the schedule is fixed.",why:"People who opened the wrong shifts need to know to look again."}],result:"The current version is November's schedule again, and Kevin's version is still in the history if anyone needs it.",takeaway:"Open it, check it, then restore. Restoring never erases the version you are replacing."},{type:"drag-drop",mode:"order",title:"Put the restore steps in order",prompt:"Drag the steps for restoring an earlier version into order.",items:[{id:"1",text:"Right-click the file and select Version history"},{id:"2",text:"Find the last good version by date and person"},{id:"3",text:"Open the version to check it"},{id:"4",text:"Select the ellipses (…) next to it › Restore"},{id:"5",text:"Let the people who use the file know"}]}]},{heading:"How long versions are kept",blocks:[{type:"paragraph",text:"In a personal OneDrive, Microsoft keeps file version history for 30 days. In a work or school OneDrive, your organization's settings decide how many earlier versions are kept, and administrators can turn versioning off. Version history only helps with files that are in OneDrive, which is one more reason to save work files there instead of on the desktop."},{type:"callout",variant:"info",text:"Version history fixes changes inside one file. If many files were changed at once, for example by ransomware, Restore your OneDrive (later in this module) can roll back your whole OneDrive."},{type:"image",src:`${l}/version-history/infographic.png`,alt:"Quick reference: version history for one changed file, the Recycle bin for deleted files, and Restore your OneDrive for many changed files",caption:"Quick reference: recover almost anything."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You restore version 4.0 of a file whose current version is 5.0. What happens to version 5.0?",options:["It is deleted","It stays in version history; the restored copy becomes the new current version","It moves to the Recycle bin","It is renamed with the word old"],correctIndex:1,explanation:"Restoring makes a copy of the older version the new current version. The version you replaced stays in the history.",optionRationales:["Restoring doesn't delete versions.","Correct.","Versions don't go to the Recycle bin; files do.","OneDrive doesn't rename anything when you restore."]},{type:"knowledge-check",question:"Why open an earlier version before restoring it?",options:["It is required before Restore is available","To confirm it is the right version, so you don't replace one mistake with another","To make a backup copy","To notify the other editors"],correctIndex:1,explanation:"Checking first makes sure you restore the version you actually want.",optionRationales:["Restore is available without opening the version first; checking is just smart.","Correct.","Opening a version doesn't make a copy.","Opening a version doesn't notify anyone."]}]}],challenge:[{type:"paragraph",text:"Use version history on a practice file in your real OneDrive."},{type:"list",ordered:!0,items:["Open Practice Notes (from Module 2) in Word for the web. Type a sentence, wait a few seconds, then type a second sentence. Close it.","In OneDrive, right-click Practice Notes and select Version history. Take a screenshot of the list.","Open an earlier version, then restore it.","Open the file and confirm the second sentence is gone. Open Version history again and confirm the version you replaced is still listed."]},{type:"callout",variant:"success",text:"Deliverable: Submit your two screenshots of version history (before and after restoring) to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"recycle-bin",title:"Recovering Deleted Files from the Recycle Bin",description:"Restore files and folders you deleted, permanently delete what you don't want, and know how long OneDrive keeps deleted items.",objectives:["Open the OneDrive Recycle bin and restore one or several items","Restore a deleted folder with everything in it","Permanently delete items and empty the Recycle bin, and know when not to","State how long work or school and personal accounts keep deleted items"],duration:"12 min",slides:m("recycle-bin",["Deleted doesn't mean gone: the Recycle bin","How long OneDrive keeps deleted items","Restore one, several, or a whole folder","Permanent delete: think twice","Deleting on your PC deletes in OneDrive too"]),sections:[{heading:"Oops",blocks:[{type:"scenario",role:"You cleaned up My files at the end of a long day.",text:"This morning the flu clinic team can't find the flyer. While tidying yesterday you selected one file too many and deleted it, along with the vendor contacts list and a folder of health fair photos.",task:"Get back what you deleted by mistake, and permanently remove only what you are sure nobody needs."},{type:"paragraph",text:"When you delete a file or folder in OneDrive, it goes to the Recycle bin, not straight out of existence. Select Recycle bin in the left pane to see what you deleted, when, and where it came from (the Original location column). Select items with their check boxes and select Restore to put them back where they were."},{type:"table",caption:"How long deleted items are kept",columns:["Account","Kept in the Recycle bin for"],rows:[["Work or school","93 days, unless your organization changed this"],["Personal","30 days"]]}]},{heading:"Restore, delete, or empty",blocks:[{type:"table",caption:"Recycle bin commands",columns:["Command","What it does"],rows:[["Restore","Puts the selected items back in their original location. Restoring a folder brings back everything that was in it"],["Delete","Permanently deletes the selected items. You can't restore them afterward"],["Empty recycle bin","Permanently deletes everything in the Recycle bin"]]},{type:"callout",variant:"warning",text:"Files permanently deleted from the Recycle bin can't be restored, not with Restore your OneDrive and not with version history. In a work account, leave permanent deletion to the retention rules unless you have a reason, and never empty the Recycle bin to hide a mistake."},{type:"drag-drop",mode:"sort",title:"Restore it or delete it permanently?",prompt:"Sort each Recycle bin item.",buckets:[{id:"restore",label:"Restore"},{id:"purge",label:"Delete permanently"}],items:[{id:"a",text:"The flu clinic flyer the team is looking for",bucket:"restore"},{id:"b",text:"A duplicate you made by accident: Old Fax Cover Sheet (copy)",bucket:"purge"},{id:"c",text:"A folder of health fair photos you deleted by mistake",bucket:"restore"},{id:"d",text:"A work file you found and removed from your personal OneDrive",bucket:"purge"}],explanation:"Restore anything someone might need. Permanently delete only when you are sure, for example an accidental duplicate, or a copy that should never have been in that account."}]},{heading:"Deleting from File Explorer",blocks:[{type:"paragraph",text:"If you use the OneDrive sync app, the OneDrive folder in File Explorer is the same OneDrive. Deleting a file there deletes it from OneDrive everywhere, and it goes to the OneDrive Recycle bin online. To free up space on your PC without deleting anything, use Free up space instead (Module 5)."},{type:"callout",variant:"info",text:"You can only restore items from your own OneDrive. If a file someone shared with you disappears, the owner deleted it, and it is in the owner's Recycle bin. Ask them to restore it."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You deleted a folder from your work OneDrive 10 days ago. Can you get it back?",options:["No, deleted folders are gone immediately","Yes, from the Recycle bin, with everything that was in it","Only the folder, not the files inside","Only if IT restores it"],correctIndex:1,explanation:"Work or school OneDrive keeps deleted items for 93 days (unless your organization changed this). Restoring a folder restores its contents.",optionRationales:["Deleted items go to the Recycle bin first.","Correct.","Restoring a folder brings back what was inside it.","You can restore it yourself from the Recycle bin."]},{type:"knowledge-check",question:"Which action can't be undone?",options:["Deleting a file in My files","Restoring a file from the Recycle bin","Deleting a file from the Recycle bin","Moving a file to another folder"],correctIndex:2,explanation:"Deleting from the Recycle bin is permanent.",optionRationales:["That sends the file to the Recycle bin, where you can restore it.","Restoring puts the file back; you could delete it again if needed.","Correct. Permanent deletion can't be undone.","Moving can be undone by moving it back."]}]}],challenge:[{type:"paragraph",text:"Practice with files you don't need in your real OneDrive."},{type:"list",ordered:!0,items:["In your OneDrive Practice folder, create two small files (for example, Delete Me 1 and Delete Me 2).","Delete both. Open the Recycle bin and take a screenshot showing them with their original location.","Restore Delete Me 1. Confirm it is back in OneDrive Practice.","Permanently delete Delete Me 2 from the Recycle bin."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Recycle bin screenshot and one sentence explaining the difference between Delete in My files and Delete in the Recycle bin to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"restore-your-onedrive",title:"Restore Your OneDrive and Ransomware Basics",description:"Recognize a ransomware attack on your files, report it the right way, and use Restore your OneDrive to roll back many files at once.",objectives:["Recognize signs that ransomware or a bad sync changed many files","Know who to tell first at work, and why you don't try to fix it alone","Use Restore your OneDrive with a date preset or a custom activity","Explain what restoring does to files created after the restore point"],duration:"15 min",slides:m("restore-your-onedrive",["When many files go wrong at once","Signs of ransomware","At work: report first","Restore your OneDrive, step by step","Pick the restore point carefully","Ransomware detection for Microsoft 365 subscribers"]),sections:[{heading:"When many files go wrong at once",blocks:[{type:"scenario",role:"You open OneDrive first thing in the morning.",text:"Overnight, five front desk files were renamed to end in .locked, none of them open, and a new file called READ_ME_TO_RECOVER.txt is demanding payment. Luis in IT confirms it: an infected home laptop that was synced to a coworker's account reached shared files. He has cleaned the laptop and asks you to roll the files back.",task:"Report it, then use Restore your OneDrive to undo the attack without undoing more than necessary."},{type:"paragraph",text:"Ransomware is malicious software that encrypts or scrambles files so they can't be opened, then demands money to unlock them. Signs include many files renamed with an unfamiliar extension, files that won't open, and a new note asking for payment. A sync accident (someone deleting or overwriting a whole folder) can look similar."},{type:"callout",variant:"warning",text:"At work, report it first. Tell your supervisor and IT immediately, don't pay anything, and don't try to fix it alone. Infected devices must be cleaned before you restore files, or they can be encrypted again. Microsoft's own steps start with confirming the files are infected and cleaning every device with antivirus software before restoring."}]},{heading:"Restore your OneDrive",blocks:[{type:"paragraph",text:"Restore your OneDrive rolls back everything that changed in your OneDrive after a point you choose, within the last 30 days. Work or school accounts have it; for personal accounts it needs a Microsoft 365 subscription."},{type:"list",ordered:!0,items:["Sign in to OneDrive on the web. Work or school account: select Settings (gear) › Restore OneDrive. Personal account: select Settings › Options › Restore your OneDrive.","Under Select a date, choose a preset (Yesterday, One week ago, Three weeks ago) or Custom date and time.","Use the activity chart and the activity feed to review what changed. With Custom date and time, select the earliest activity you want to undo; every activity after it is selected too.","Select Restore and confirm."]},{type:"table",caption:"What restoring does",columns:["Item","After the restore"],rows:[["Files changed after the restore point","Go back to how they were"],["Files deleted after the restore point","Come back"],["Files created after the restore point","Move to the Recycle bin, where you can still restore them"],["Files permanently deleted from the Recycle bin","Can't be recovered"]]},{type:"callout",variant:"info",text:"Every activity after the restore point is undone, including good work. Pick the earliest bad activity, not an earlier date, and redo any legitimate changes afterward. If you restored to the wrong point, run Restore again and select the restore activity to undo it."},{type:"drag-drop",mode:"order",title:"Put the response in order",prompt:"Drag these steps into the order you should do them after a ransomware attack at work.",items:[{id:"1",text:"Tell your supervisor and IT right away"},{id:"2",text:"IT cleans the infected devices"},{id:"3",text:"Open Settings › Restore OneDrive"},{id:"4",text:"Choose Custom date and time and select the earliest bad activity"},{id:"5",text:"Select Restore, then check your files"}]}]},{heading:"Ransomware detection for Microsoft 365 subscribers",blocks:[{type:"paragraph",text:"With a Microsoft 365 subscription on a personal account, Microsoft 365 can detect a ransomware attack on your OneDrive files. You get a notification on your device and an email, and when you go to restore, a suggested restore date is filled in for you. (Microsoft says non-subscribers get their first detection and recovery free.)"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You find dozens of front desk files renamed to end in .locked and a payment note. What do you do first?",options:["Run Restore your OneDrive right away","Pay the ransom so the files unlock quickly","Tell your supervisor and IT immediately","Delete the payment note and keep working"],correctIndex:2,explanation:"Report it first. IT has to clean the infected devices before a restore, or the files can be encrypted again.",optionRationales:["Restoring before the devices are cleaned can lead to a second attack.","Never pay. It doesn't guarantee anything and rewards the attackers.","Correct.","Ignoring it lets the damage spread."]},{type:"knowledge-check",question:"After you restore your OneDrive to yesterday at 9 PM, what happens to a file you created this morning?",options:["It is permanently deleted","It stays exactly as it is","It moves to the Recycle bin, where you can restore it","It is renamed"],correctIndex:2,explanation:"Files created after the restore point move to the Recycle bin, so you can still bring them back.",optionRationales:["It isn't permanently deleted.","Everything after the restore point is undone, including new files.","Correct.","Restore doesn't rename new files."]}]}],challenge:[{type:"paragraph",text:"Don't restore your real OneDrive for practice; it would undo your real work. Look, then practice the restore in the Challenge Lab."},{type:"list",ordered:!0,items:["Sign in to OneDrive on the web with your school account and open Settings › Restore OneDrive (personal accounts: Settings › Options › Restore your OneDrive).","Choose One week ago under Select a date and look at the activity chart and feed. Take a screenshot. Then leave the page without selecting Restore.","Do the full restore in the Challenge Lab below: report the attack, roll back to the earliest bad activity, and remove the ransom note."]},{type:"callout",variant:"success",text:"On a school computer, do this in the Challenge Lab below. Deliverable: Submit your Challenge Lab results page (Print or save results on the finish card), plus your screenshot from step 2 if you took it, to your instructor or course folder."}]},{slug:"account-security-and-personal-vault",title:"Protecting Your Account and Personal Vault",description:"Keep your OneDrive account safe with multifactor authentication and good sign-in habits, spot fake sharing emails, and use Personal Vault for your own most sensitive files.",objectives:["Explain why multifactor authentication and signing out protect your files","Spot a fake file-sharing email and check it safely","Use Personal Vault in a personal OneDrive: unlock, add files, and lock","Scan documents with the OneDrive mobile app now that Microsoft Lens is retired"],duration:"15 min",slides:m("account-security-and-personal-vault",["Your account is the key to every file","Spot a fake file-sharing email","Personal Vault: a locked folder for your own sensitive files","Unlock, add, lock","Scanning with the OneDrive app (Microsoft Lens is retired)"]),sections:[{heading:"Your account is the key",blocks:[{type:"scenario",role:"You use OneDrive at work and at home.",text:"An email says Maria Santos shared Payroll Update.pdf with you and asks you to sign in to view it. The sender's address is maria.santos@lakeside-files.example, not Lakeside's real domain. At home, you also want somewhere safer than a regular folder for scans of your own ID and insurance card.",task:"Protect your accounts, check suspicious sharing emails safely, and use Personal Vault for your own sensitive documents."},{type:"list",items:["Turn on multifactor authentication (MFA). With MFA, a stolen password alone isn't enough to get in. Work accounts usually require it; for a personal Microsoft account, turn on two-step verification in your account's security settings.","Use a strong, unique password (or a passkey, if offered) for each account. Never reuse your work password.","Sign out of OneDrive on any shared computer, and close the browser.","Never give anyone your password, including a coworker who 'just needs one file.' Share the file instead."]}]},{heading:"Spotting a fake sharing email",blocks:[{type:"paragraph",text:"Attackers copy the look of real sharing emails to trick people into typing their password on a fake sign-in page. Check before you click: Is the sender's address from the real organization? Did you expect this file? Point to the link (don't click) and look at where it really goes. The safest check is to skip the email: open OneDrive yourself and look in Shared. If the file was really shared with you, it is there."},{type:"drag-drop",mode:"sort",title:"Real or suspicious?",prompt:"Sort each sign.",buckets:[{id:"ok",label:"Normal"},{id:"sus",label:"Suspicious: check in OneDrive or report it"}],items:[{id:"a",text:"The sender's address uses a look-alike domain",bucket:"sus"},{id:"b",text:"A file you were expecting from your manager, and it is also in Shared",bucket:"ok"},{id:"c",text:"The link goes to a web address that isn't Microsoft's or your organization's",bucket:"sus"},{id:"d",text:"The email says your account will be closed unless you sign in now",bucket:"sus"}],explanation:"Look-alike addresses, unexpected urgency, and links that don't go where they claim are classic phishing signs. When in doubt, open OneDrive directly and report the email to IT."}]},{heading:"Personal Vault",blocks:[{type:"paragraph",text:"Personal Vault is a protected folder in a personal OneDrive (it isn't available in work or school accounts). To open it you verify your identity again, with a code sent by text or email or with the Microsoft Authenticator app. On the web it locks itself after 20 minutes of inactivity; in the mobile app it locks after 3 minutes by default. Without a Microsoft 365 subscription you can keep up to three files in it; with Microsoft 365 Basic, Personal, or Family you can keep as many as your storage allows. Use it for your own sensitive documents: a copy of your ID, insurance cards, tax forms. It is never a place for work files or patient information."},{type:"worked-example",title:"Moving your ID scan into Personal Vault",task:"Protect the scans of your passport and car insurance card in your personal OneDrive.",steps:[{move:"In My files, open Personal Vault and select Unlock.",why:"The vault asks you to verify your identity, so a person who gets into your account still can't open it without your second factor."},{move:"Choose a verification method and enter the code.",why:"Text, email, or the Authenticator app all prove it is you."},{move:"Move the two scans into Personal Vault.",why:"Moving keeps one copy, now in the protected folder."},{move:"Delete any old copies from the Recycle bin, then select Lock.",why:"Old copies outside the vault would undo the point. Locking now means you don't wait 20 minutes for it to lock itself."}],result:"Your sensitive scans are in a folder that needs a second verification to open.",takeaway:"Personal Vault is for your own most sensitive files. Lock it when you are done."}]},{heading:"Scanning documents with your phone",blocks:[{type:"callout",variant:"version",text:"Microsoft Lens, the old scanning app, was retired: it was removed from the app stores on February 9, 2026, and stopped creating new scans on March 9, 2026. Microsoft's recommended replacement is the OneDrive mobile app's built-in scanner: open OneDrive on your phone, tap the plus (+) button, choose the scan option, and save the scan to a OneDrive folder. In a personal OneDrive you can scan straight into Personal Vault."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"An email says a coworker shared a file and asks you to sign in. The sender's domain looks slightly wrong. What is the safest move?",options:["Click the link and sign in quickly to check","Forward it to the whole office as a warning","Open OneDrive yourself and check Shared; report the email to IT","Reply and ask if it's real"],correctIndex:2,explanation:"If the share is real, the file is in Shared. Going to OneDrive directly avoids a fake sign-in page, and reporting helps IT protect everyone.",optionRationales:["That is exactly what the attacker wants.","Forwarding spreads the dangerous link. Report it to IT instead.","Correct.","Replying goes to the attacker."]},{type:"knowledge-check",question:"Which account can use Personal Vault?",options:["Work or school accounts","Personal Microsoft accounts","Both","Neither"],correctIndex:1,explanation:"Personal Vault is a feature of personal OneDrive. Work or school accounts don't have it.",optionRationales:["Work or school accounts don't have Personal Vault.","Correct.","Only personal accounts have it.","Personal accounts have it."]}]}],challenge:[{type:"paragraph",text:"Check your own account security."},{type:"list",ordered:!0,items:["Sign in at mysignins.microsoft.com/security-info with your school account and look at your sign-in methods. Write down which methods are set up (don't share codes or phone numbers).","Find one phishing example online from Microsoft or your school's IT page, or describe a suspicious email you received, and list two warning signs.","If you have a personal Microsoft account, open Personal Vault on your own device and look at how it locks. If you don't, describe in two sentences what you would put in it and why."]},{type:"callout",variant:"success",text:"Deliverable: Submit your written answers to your instructor or course folder. If you can't do step 3, complete this lesson's practice simulation and submit its results page."}]}],o="/images/ms-office/onedrive/module-5",p=(a,b)=>b.map((b,c)=>({src:`${o}/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),q=[{slug:"the-sync-app",title:"The OneDrive Sync App and File Explorer",description:"Use OneDrive from File Explorer: the OneDrive folder, the cloud icon and activity center, pausing and resuming sync, and what to do about sync problems.",objectives:["Find your OneDrive folder in File Explorer and save files into it","Open the activity center from the OneDrive cloud icon and read its status","Pause syncing for 2, 8, or 24 hours and resume it","Recognize a sync problem and know where to look for the cause"],duration:"15 min",slides:p("the-sync-app",["The sync app puts OneDrive in File Explorer","The cloud icon and the activity center","Pause and resume syncing","When something won't sync","Work and school computers are managed by IT"]),sections:[{heading:"OneDrive without a browser",blocks:[{type:"scenario",role:"You work at the front desk computer at Lakeside.",text:"You have been opening OneDrive in a browser all morning. Maria points to the cloud icon at the bottom right of your screen: the OneDrive sync app is already set up on this computer. Your OneDrive is right there in File Explorer, and anything you save into it is in OneDrive everywhere.",task:"Use OneDrive from File Explorer, check that files are synced, and pause syncing when the network is busy."},{type:"paragraph",text:"The OneDrive sync app comes with Windows 11. Once you sign in, it adds a folder to File Explorer named for your account: OneDrive - Lakeside Medical Associates for a work account, or OneDrive - Personal. That folder is your OneDrive. Files you save there upload automatically, and changes made on another device download automatically. You can also save into it from any app with File › Save As and the OneDrive location."},{type:"table",caption:"The OneDrive cloud icon and activity center",columns:["Part","What it is for"],rows:[["Cloud icon (notification area, bottom right)","Select it to open the activity center. A paused symbol or a red mark on it means syncing is paused or has a problem"],["Activity center","Recent uploads, sync status, and sync problems"],["Open folder","Opens your OneDrive folder in File Explorer"],["View online","Opens OneDrive on the web"],["Help & Settings (gear)","Settings, Pause syncing, and Quit OneDrive"]]}]},{heading:"Pausing and resuming",blocks:[{type:"paragraph",text:"Syncing uses your network connection. If you need all of it for a moment, for example during a video visit on a slow connection, pause syncing. Right-click the OneDrive cloud icon (or open the activity center and select Help & Settings), select Pause syncing, and choose 2 hours, 8 hours, or 24 hours. The cloud icon shows that syncing is paused. To start again before the time is up, open the activity center and select the paused message (or Help & Settings › Resume syncing)."},{type:"callout",variant:"warning",text:"While syncing is paused, your changes are only on this computer. Resume as soon as you can, and never shut down a computer that is uploading important files."}]},{heading:"When something won't sync",blocks:[{type:"paragraph",text:"A file with a problem shows a red circle with an X in File Explorer, and the cloud icon shows a red mark. Open the activity center to see which file and why. Common causes are a name OneDrive doesn't allow (it can't contain \" * : < > ? / \\ |), not enough space in your OneDrive, or a file that is open in another app. Fix the cause (rename the file, free up space, or close the file) and OneDrive tries again. At work, if you can't tell what is wrong, contact IT before moving or deleting anything."},{type:"drag-drop",mode:"match",title:"Read the cloud icon",prompt:"Drag each meaning onto what you see.",items:[{id:"a",text:"Cloud icon with a pause symbol",match:"Syncing is paused"},{id:"b",text:"Cloud icon with a red mark",match:"Something can't sync; open the activity center"},{id:"c",text:"Activity center says your files are synced",match:"Everything is up to date"},{id:"d",text:"Activity center lists a file as Uploaded to OneDrive",match:"That file just finished syncing"}]},{type:"callout",variant:"info",text:"Work and school computers are usually set up by IT. They may sign you in to the sync app automatically, back up your folders for you, or lock some settings. If a setting is greyed out, that is why. On BEOC classroom computers the sync app settings may be blocked, so this lesson's challenge has a Challenge Lab."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You save a file into the OneDrive - Lakeside Medical Associates folder in File Explorer. Where is it?",options:["Only on this computer","In your OneDrive, available on the web and your other devices","In the team's SharePoint library","In your email"],correctIndex:1,explanation:"That folder is your OneDrive. The sync app uploads what you save there.",optionRationales:["The sync app uploads it to OneDrive automatically.","Correct.","Your OneDrive folder is yours, not the team's library.","Saving to a folder doesn't email anything."]},{type:"knowledge-check",question:"Which pause lengths does OneDrive offer?",options:["15 minutes, 1 hour, or 4 hours","2 hours, 8 hours, or 24 hours","Until you restart","1 day or 1 week"],correctIndex:1,explanation:"Pause syncing offers 2, 8, or 24 hours. You can resume sooner.",optionRationales:["Those aren't the options.","Correct.","Pausing is for a set time.","Those aren't the options."]}]}],challenge:[{type:"paragraph",text:"On your own Windows 11 computer, use the real sync app. On a school computer, the sync app settings may be blocked by IT."},{type:"list",ordered:!0,items:["Open File Explorer and select your OneDrive folder in the navigation pane. Take a screenshot showing the Status column.","Create a folder named OneDrive Sync Practice in your OneDrive folder.","Select the OneDrive cloud icon to open the activity center. Pause syncing for 2 hours, take a screenshot of the paused cloud icon or message, then resume syncing.","From the activity center, select View online and find OneDrive Sync Practice on the web."]},{type:"callout",variant:"success",text:"On a school computer, do this in the Challenge Lab below. Deliverable: Submit your screenshots, or your Challenge Lab results page (Print or save results on the finish card), to your instructor or course folder."}]},{slug:"files-on-demand",title:"Files On-Demand: Online-Only and Always Available",description:"Read the status icons in File Explorer, keep important files on your PC for offline work, free up disk space, and use OneDrive when you are offline.",objectives:["Identify online-only, locally available, and always available files by their icons","Use Always keep on this device and Free up space","Use Free up disk space and Download all files in OneDrive settings","Prepare files for work without an internet connection"],duration:"15 min",slides:p("files-on-demand",["Files On-Demand: see everything, store only what you need","Three status icons","Always keep on this device, and Free up space","Settings: Free up disk space or Download all files","Working offline"]),sections:[{heading:"All your files, without filling the drive",blocks:[{type:"scenario",role:"You are packing the laptop for the community health fair.",text:"The health fair is in a gym with no reliable Wi-Fi. You need the patient forms on the laptop, but the laptop's drive is almost full, mostly with old training videos you rarely watch.",task:"Make sure the forms are on the laptop for offline use, and free up space from files that can stay in the cloud."},{type:"paragraph",text:"Files On-Demand lets File Explorer show every file in your OneDrive without downloading all of them. A file can be online-only (it takes no space and downloads when you open it), locally available (downloaded because you opened it), or always available (kept on the device on purpose). Starting with OneDrive build 23.066, Files On-Demand is turned on by default."},{type:"table",caption:"Status icons in File Explorer's Status column",columns:["Icon","Status","Means"],rows:[["Blue cloud outline","Online-only","Takes no space on this PC. Opens only when you are connected to the internet"],["Green check in a white circle","Available on this device","Downloaded when you opened it. Opens offline. Free up space can make it online-only again"],["White check in a solid green circle","Always available","You chose Always keep on this device. Stays on the PC and opens offline"],["Blue circular arrows","Syncing","Uploading or downloading now"],["Red circle with an X","Sync problem","Open the activity center to see why"]]},{type:"drag-drop",mode:"match",title:"Match the icon to its meaning",prompt:"Drag each meaning onto its status icon.",items:[{id:"a",text:"Blue cloud outline",match:"Online-only: needs internet to open"},{id:"b",text:"Green check in a white circle",match:"Downloaded because you opened it"},{id:"c",text:"White check in a solid green circle",match:"Always kept on this device"},{id:"d",text:"Red circle with an X",match:"Has a sync problem"}]},{type:"image",src:`${o}/files-on-demand/infographic.png`,alt:"Quick reference: Files On-Demand status icons, the Always keep on this device and Free up space commands, and the Advanced settings choices",caption:"Quick reference: Files On-Demand status icons."}]},{heading:"Choosing what stays on the PC",blocks:[{type:"list",items:["Always keep on this device: right-click a file or folder in your OneDrive folder and select it. Everything inside downloads and stays, so you can open it offline.","Free up space: right-click a file or folder and select it. The files become online-only and stop taking space, but they stay in OneDrive and in File Explorer.","For everything at once, open OneDrive settings (cloud icon › Help & Settings › Settings) › Sync and backup › Advanced settings. Free up disk space (the recommended choice) makes files online-only; Download all files keeps everything on the device."]},{type:"worked-example",title:"Packing for the health fair",task:"Keep the patient forms on the laptop and reclaim space from training videos.",steps:[{move:"Right-click the Patient Forms folder › Always keep on this device.",why:"Every form downloads now and stays on the laptop, so it opens in a gym with no Wi-Fi."},{move:"Watch the Status column until each form shows the solid green circle.",why:"The icon confirms the files are really on the laptop before you leave the office."},{move:"Right-click the Training folder › Free up space.",why:"The videos become online-only. They still appear in File Explorer and download if someone opens them later."}],result:"The forms work offline and the drive has room again.",takeaway:"Always keep what you need offline; free up space on what can wait for the internet."},{type:"callout",variant:"info",text:"OneDrive on the web also has an offline mode for work or school accounts on Windows and Mac computers with the sync app. It is on by default, and while you are offline you can still view, rename, move, and copy files and create folders in the OneDrive web app."},{type:"callout",variant:"warning",text:"Free up space isn't Delete. Deleting a file in your OneDrive folder deletes it from OneDrive everywhere (it goes to the OneDrive Recycle bin). Use Free up space when the goal is disk space."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"A file shows a blue cloud outline. What happens if you try to open it with no internet connection?",options:["It opens normally","It can't open until you are connected","It opens read-only","It is deleted"],correctIndex:1,explanation:"Online-only files aren't stored on the PC, so they need the internet to download when you open them.",optionRationales:["Online-only files aren't on the PC yet.","Correct.","There is nothing local to open, read-only or otherwise.","Nothing is deleted."]},{type:"knowledge-check",question:"Your laptop is low on space. Which choice keeps every file in OneDrive but stops them from taking space on the laptop?",options:["Delete the files","Free up space","Always keep on this device","Pause syncing"],correctIndex:1,explanation:"Free up space makes files online-only. They stay in OneDrive and still show in File Explorer.",optionRationales:["Deleting removes them from OneDrive everywhere.","Correct.","That does the opposite: it keeps files on the device.","Pausing stops syncing but doesn't free any space."]}]}],challenge:[{type:"paragraph",text:"On your own computer with the OneDrive sync app, try Files On-Demand. On a school computer, use the Challenge Lab."},{type:"list",ordered:!0,items:["In File Explorer, open your OneDrive folder and find one file with each status: online-only, available on this device, and always available (you may need to create them in the next steps). Take a screenshot.","Right-click your OneDrive Sync Practice folder (or any practice folder) and select Always keep on this device. Take a screenshot when the icon is a solid green circle.","Right-click the same folder and select Free up space. Take a screenshot of the cloud icon."]},{type:"callout",variant:"success",text:"On a school computer, do this in the Challenge Lab below. Deliverable: Submit your three screenshots, or your Challenge Lab results page (Print or save results), to your instructor or course folder."}]},{slug:"backing-up-pc-folders",title:"Backing Up Your Desktop, Documents, and Pictures",description:"Turn on OneDrive folder backup so the files people keep on the desktop and in Documents are protected and available on other devices.",objectives:["Explain what folder backup does to your Desktop, Documents, and Pictures folders","Turn folder backup on with Manage backup","Explain what happens when you stop backing up a folder","Recognize when your organization manages folder backup for you"],duration:"12 min",slides:p("backing-up-pc-folders",["The desktop is the riskiest place to keep files","Folder backup moves Desktop, Documents, and Pictures into OneDrive","Turn it on: Settings › Sync and backup › Manage backup","Stopping backup: choose where the files stay","Your organization may manage this for you"]),sections:[{heading:"Files on the desktop aren't backed up",blocks:[{type:"scenario",role:"You are setting up a replacement PC at the check-in window.",text:"When the old check-in computer died, everything on its desktop died with it: the lunch order form, the holiday signup sheet, a dozen screenshots. Maria wants the new PC set up so that never happens again.",task:"Back up the Desktop and Documents folders to OneDrive so they survive a broken computer."},{type:"paragraph",text:"Folder backup (IT departments may call it Known Folder Move) makes your PC's Desktop, Documents, and Pictures folders part of OneDrive. Files in them sync like any other OneDrive file: they are backed up, they open on your other devices, and they get version history and the Recycle bin. You keep working exactly where you always did; the desktop simply lives in OneDrive now."}]},{heading:"Turning it on",blocks:[{type:"list",ordered:!0,items:["Select the OneDrive cloud icon in the notification area, then Help & Settings › Settings.","Select the Sync and backup tab, then Manage backup.","Turn on the toggle for each folder marked Not backed up.","Select Save changes. The folders start syncing."]},{type:"drag-drop",mode:"order",title:"Put the backup steps in order",prompt:"Drag the steps for turning on folder backup into order.",items:[{id:"1",text:"Select the OneDrive cloud icon"},{id:"2",text:"Select Help & Settings › Settings"},{id:"3",text:"Open Sync and backup › Manage backup"},{id:"4",text:"Turn on the folders you want to back up"},{id:"5",text:"Select Save changes"}]},{type:"callout",variant:"info",text:"To stop backing up a folder, turn its toggle off. OneDrive asks where the files should stay: only in OneDrive (they leave the PC) or only on this PC (they leave OneDrive). If some files are online-only, OneDrive asks you to download them first with Always keep on this device."}]},{heading:"When IT is in charge",blocks:[{type:"paragraph",text:"On work and school computers, IT often turns folder backup on for everyone or blocks it. If Manage backup is greyed out or the folders already show Backed up, that is your organization's setting. A personal Microsoft account can't back up folders on a PC that is joined to an organization's domain; talk to IT there."},{type:"callout",variant:"warning",text:"Backing up the desktop doesn't make it the right place for patient information. Patient files still belong in the approved location your office uses."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"After you turn on backup for Desktop, where are the files on your desktop stored?",options:["Only on the PC","In OneDrive, and they still show on the desktop","In the Recycle bin","In a ZIP file"],correctIndex:1,explanation:"The Desktop folder becomes part of OneDrive. You keep using it the same way, but the files are synced and backed up.",optionRationales:["That was the risk before backup.","Correct.","Nothing is deleted.","No ZIP file is made."]},{type:"knowledge-check",question:"Manage backup is greyed out on your work computer. What does that most likely mean?",options:["OneDrive is broken","Your organization manages folder backup","You need a personal account","Your desktop is empty"],correctIndex:1,explanation:"IT can turn folder backup on for everyone or prevent changes. Ask IT if you need it changed.",optionRationales:["A managed setting isn't a broken app.","Correct.","A personal account can't back up folders on a domain-joined work PC.","An empty desktop can still be backed up."]}]}],challenge:[{type:"paragraph",text:"On your own Windows computer, back up a folder. School computers usually block this, so use the Challenge Lab there."},{type:"list",ordered:!0,items:["Open OneDrive settings (cloud icon › Help & Settings › Settings) › Sync and backup › Manage backup. Take a screenshot.","Turn on backup for Documents (and Desktop if you like), then select Save changes.","Open OneDrive on the web and find the Documents folder there. Take a screenshot."]},{type:"callout",variant:"success",text:"On a school computer, do this in the Challenge Lab below. Deliverable: Submit your two screenshots, or your Challenge Lab results page (Print or save results), to your instructor or course folder."}]}],r=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/onedrive/module-6/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),s=[{moduleNumber:1,moduleSlug:"module-1",title:"Getting Started with OneDrive",emoji:"☁️",description:"What OneDrive is, signing in, finding your way around OneDrive on the web, and work versus personal accounts.",lessons:f,level:"Beginner",estimatedMinutes:45},{moduleNumber:2,moduleSlug:"module-2",title:"Organizing Your Files",emoji:"\uD83D\uDDC2️",description:"Upload files and folders, create folders and Office files, move, copy, rename and delete, and find any file fast with Search, Favorites, and shortcuts.",lessons:h,level:"Beginner",estimatedMinutes:45},{moduleNumber:3,moduleSlug:"module-3",title:"Sharing and Collaboration",emoji:"\uD83E\uDD1D",description:"Share with the right permission and the right kind of link, manage and remove access, and co-author with comments and @mentions. Patient information is never shared with an Anyone link.",lessons:k,level:"Beginner",estimatedMinutes:50},{moduleNumber:4,moduleSlug:"module-4",title:"Keeping Files Safe",emoji:"\uD83D\uDEE1️",description:"Restore earlier versions, recover deleted files, roll back your whole OneDrive after ransomware, protect your account, and use Personal Vault.",lessons:n,level:"Intermediate",estimatedMinutes:55},{moduleNumber:5,moduleSlug:"module-5",title:"Syncing with Your PC",emoji:"\uD83D\uDD04",description:"Use OneDrive from File Explorer with the sync app, read Files On-Demand status icons, keep files for offline work, free up space, and back up your Desktop and Documents.",lessons:q,level:"Intermediate",estimatedMinutes:45},{moduleNumber:6,moduleSlug:"module-6",title:"OneDrive with Teams, Outlook, and Office",emoji:"\uD83D\uDD17",description:"Know where Teams stores chat, channel, and meeting files, send links instead of attachments, and use AutoSave and version history in the Office apps.",lessons:[{slug:"onedrive-sharepoint-and-teams",title:"Where Files Live: OneDrive, SharePoint, and Teams",description:"Know where Teams stores the files you share in chats, channels, and meetings, find them in OneDrive, and add team folders to My files.",objectives:["Explain where files shared in a Teams chat, a channel, and a meeting are stored","Find Teams files in OneDrive: Microsoft Teams Chat Files, Recordings, Meetings, and Quick access","Add a shortcut to a team library folder in My files","Decide whether a file belongs in your OneDrive or in a team's library"],duration:"15 min",slides:r("onedrive-sharepoint-and-teams",["One set of files, many doorways","Teams chats: your OneDrive","Teams channels: the team's SharePoint site","Meeting recordings","Find Teams files in OneDrive"]),sections:[{heading:"Where did that Teams file go?",blocks:[{type:"scenario",role:"You use Teams and OneDrive every day at Lakeside.",text:"Kevin sent you a billing spreadsheet in a Teams chat last week. Maria posted the updated procedures in the Front Desk channel. And the Monday huddle was recorded. Today you need all three, and you only have OneDrive open.",task:"Know where Teams put each file and find it from OneDrive."},{type:"table",caption:"Where Teams stores files",columns:["You share a file…","It is stored in…","Who can open it"],rows:[["In a Teams chat (one-on-one or group)","The sender's OneDrive, in the folder Microsoft Teams Chat Files","The people in that chat (Teams sets the permissions)"],["In a standard Teams channel","The team's SharePoint site, in that channel's folder of the Documents library","The members of the team"],["A meeting recording (not a channel meeting)","The organizer's OneDrive, in the Recordings folder","Meeting participants, as the organizer's settings allow"],["A channel meeting recording","The team's SharePoint site, in a Recordings folder in the channel's files","The members of the team"]]},{type:"callout",variant:"version",text:"In current Teams, a channel's files are on its Shared tab (it used to be called the Files tab). See the Microsoft Teams course for working with files inside Teams."}]},{heading:"Finding Teams files from OneDrive",blocks:[{type:"list",items:["Files you sent in chats: My files › Microsoft Teams Chat Files.","Files others sent you in chats: Shared › Shared with you (the Shared in column says which chat).","Files from a meeting: Browse files by › Meetings, then the meeting.","A team's library: Quick access in the left pane lists team libraries you use often. Open one to see the team's files.","A team folder you use every day: select it and choose Add shortcut to My files."]},{type:"drag-drop",mode:"sort",title:"Where is it stored?",prompt:"Sort each file by where Teams stored it.",buckets:[{id:"mine",label:"Your OneDrive"},{id:"team",label:"The team's SharePoint site"}],items:[{id:"a",text:"A spreadsheet you sent Kevin in a one-on-one chat",bucket:"mine"},{id:"b",text:"Procedures Maria posted in the Front Desk channel",bucket:"team"},{id:"c",text:"The recording of a meeting you organized from your calendar",bucket:"mine"},{id:"d",text:"The recording of a meeting held in the Front Desk channel",bucket:"team"},{id:"e",text:"A photo you shared in a group chat you started",bucket:"mine"}],explanation:"Chats and the meetings you organize use your OneDrive. Channels use the team's SharePoint site."},{type:"callout",variant:"warning",text:"When people leave an organization, their OneDrive is usually removed after a while, and the chat files and recordings in it go with it. Files the team must keep belong in the team's channel or library, not in one person's chat."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You shared a schedule with two coworkers in a Teams group chat you started. Where is the file?",options:["In the team's SharePoint site","In your OneDrive, in Microsoft Teams Chat Files","In each coworker's OneDrive","Only inside Teams, not in OneDrive"],correctIndex:1,explanation:"Chat files are stored in the sender's OneDrive, in Microsoft Teams Chat Files, and shared with the people in the chat.",optionRationales:["Channels use SharePoint; chats don't.","Correct.","There is one copy, in the sender's OneDrive.","Teams stores it in OneDrive, so you can find it there."]},{type:"knowledge-check",question:"The front desk team's procedures must stay available even if the person who wrote them leaves. Where should they be?",options:["In a Teams chat","In the writer's My files","In the team's channel or library","On the front desk computer's desktop"],correctIndex:2,explanation:"A team library belongs to the team, so the file stays when people come and go.",optionRationales:["Chat files live in one person's OneDrive.","One person's OneDrive leaves with them.","Correct.","A desktop is one computer, with none of OneDrive's protection."]}]}],challenge:[{type:"paragraph",text:"Explore your real OneDrive (OneDrive on the web works on BEOC classroom computers)."},{type:"list",ordered:!0,items:["Sign in at onedrive.com. In My files, look for a Microsoft Teams Chat Files folder or a Recordings folder. Write down what you find (it is fine if they don't exist yet).","Open Browse files by › Meetings and People. Write one sentence about what each shows for your account.","If Quick access lists any libraries, open one and write down its name.","Write two sentences: which of your files belong in your OneDrive, and which would belong in a team library if you worked at Lakeside."]},{type:"callout",variant:"success",text:"Deliverable: Submit your notes to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"sending-links-not-attachments",title:"Sending Files as Links Instead of Attachments",description:"Send coworkers a link to the one real file instead of an attached copy, choose what the link allows, and know when a copy (or a secure method) is the right call.",objectives:["Explain why a link beats an attachment for files people work on","Send a file from OneDrive with Share and a message, or with Copy link","Choose link permissions when attaching a OneDrive file in the new Outlook","Recognize when to attach a copy or use your office's secure method instead"],duration:"12 min",slides:r("sending-links-not-attachments",["Attachments make copies. Links share the file","Send from OneDrive: Share › Send, or Copy link","Attaching a OneDrive file in the new Outlook","When a copy is the right call"]),sections:[{heading:"Five copies of one report",blocks:[{type:"scenario",role:"You send the monthly supply report to the practice administrator.",text:"Last month you attached the supply report to an email for Renee. She forwarded it to Kevin, who made changes and sent it back, while Maria edited her own copy. By the end of the week there were five versions and nobody knew which was right.",task:"Send links to the one real file, with the right permission, and know when a copy is actually what you want."},{type:"table",caption:"Link or attachment?",columns:["","Link to a OneDrive file","Attached copy"],rows:[["How many versions","One, always current","One per person, out of date the moment it is sent"],["Email size","Small","Large files can be too big to send"],["Who can open it","Only people the link works for","Anyone the email reaches, including forwards"],["Changing your mind","Remove access or stop sharing anytime","You can't take a copy back"]]}]},{heading:"Sending a link",blocks:[{type:"list",items:["From OneDrive: select the file › Share, add people, choose the permission, type a message, and select Send. OneDrive emails them a link.","Or select Copy link, check who the link works for (the gear), select Copy, and paste the link in your email or Teams message.","In the new Outlook for Windows: in a new message, select Attach file and pick a file from OneDrive (or Suggested files). You choose whether to send a link or a copy. For a link, select the arrow on the attachment to change permissions: Organization can Edit, Organization can View, Recipients can Edit, or Recipients can View. In a business account the default lets everyone in your organization edit, so check it before you send."]},{type:"callout",variant:"info",text:"The Microsoft Outlook course covers attachments in classic Outlook and Outlook on the web. The idea is the same everywhere: a link shares the one real file, and its permission decides what people can do."}]},{heading:"When a copy is right",blocks:[{type:"paragraph",text:"Send a copy (often a PDF) when the other person needs a fixed record that shouldn't change, such as a signed form or a final invoice, or when they can't sign in to see a link. And for patient information, follow your office's approved secure method; sometimes that is a link shared with one named person, and sometimes it is a secure messaging or fax system. Never attach patient information to a regular email because it is faster."},{type:"drag-drop",mode:"sort",title:"Link, copy, or secure method?",prompt:"Sort each situation.",buckets:[{id:"link",label:"Send a link"},{id:"copy",label:"Send a copy (PDF)"},{id:"secure",label:"Use the office's approved secure method"}],items:[{id:"a",text:"Kevin and Maria both need to update the supply report",bucket:"link"},{id:"b",text:"A vendor needs the final signed W-9 form for their records",bucket:"copy"},{id:"c",text:"A specialist's office asks for a patient's records",bucket:"secure"},{id:"d",text:"The office manager should review the draft flyer",bucket:"link"},{id:"e",text:"An outside partner who can't sign in needs the final event program",bucket:"copy"}],explanation:"Use links for files people work on together, copies for fixed records, and your office's approved process for anything with patient information."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"You attach a OneDrive file as a link in the new Outlook at work and don't change anything. Who can edit it by default?",options:["Only you","Only the recipients","Everyone in your organization","Anyone on the internet"],correctIndex:2,explanation:"In a business account, the default link lets everyone in your organization edit. Change it with the arrow on the attachment if that is too much access.",optionRationales:["The link gives access to others, not only you.","Recipients can Edit is an option you can choose, but it isn't the default.","Correct.","The default stays inside your organization."]},{type:"knowledge-check",question:"Why is a link better than an attachment for a report several coworkers update?",options:["Links are always more secure","Everyone works in the one current file instead of separate copies","Attachments can't be opened on phones","Links make the file smaller"],correctIndex:1,explanation:"A link points everyone to the same file, so there is one current version.",optionRationales:["A link is only as safe as its settings. Choose who it works for.","Correct.","Attachments open on phones too.","The file is the same size; the email is smaller."]}]}],challenge:[{type:"paragraph",text:"Send a link instead of an attachment in your real accounts."},{type:"list",ordered:!0,items:["In OneDrive on the web, select a practice file and select Share. Add your instructor or a classmate with Can view and a one-line message. Take a screenshot before you select Send.","Select Copy link for another practice file and paste the link into an email to yourself from your school email. Take a screenshot of the email showing the link.","Write one sentence about a time a link would have been better than an attachment, and one about a time a copy would be better."]},{type:"callout",variant:"success",text:"Deliverable: Submit your two screenshots and two sentences to your instructor or course folder. If you cannot sign in, submit this lesson's practice simulation results page instead."}]},{slug:"autosave-and-office-apps",title:"AutoSave and Office Apps with OneDrive",description:"Open OneDrive files in the Office desktop apps, keep AutoSave on, save new files to OneDrive, and use version history from inside Word, Excel, and PowerPoint.",objectives:["Open a OneDrive file in the browser or in the desktop app","Explain AutoSave and turn it on for a file stored in OneDrive","Save a new file to OneDrive from an Office app","Open version history from the file name in an Office app's title bar"],duration:"12 min",slides:r("autosave-and-office-apps",["Open in browser, or open in app","AutoSave: on for files in OneDrive","Save new files to OneDrive from the start","Version history from the title bar"]),sections:[{heading:"The browser or the app",blocks:[{type:"scenario",role:"You are finishing the Check-In Procedures in Word.",text:"You need a feature that is only in the desktop version of Word, so you open the file in the app. Halfway through, you notice AutoSave in the corner is off. If the computer restarts for an update, your last hour of work could be gone.",task:"Open the file in the app, turn AutoSave on, and know how to get back to an earlier version."},{type:"paragraph",text:"Selecting a Word, Excel, or PowerPoint file's name in OneDrive opens it in the browser (Word for the web, and so on), which works on any computer. For features that only the desktop apps have, right-click the file in OneDrive and select Open › Open in app. Either way, you are working in the same file in OneDrive, so co-authors, comments, and version history all still apply."}]},{heading:"AutoSave",blocks:[{type:"paragraph",text:"AutoSave, in the top left corner of the Microsoft 365 desktop apps, saves your changes to OneDrive every few seconds. It is turned on by default for files stored in OneDrive or SharePoint, and it is what lets co-authors see your changes. The title bar shows the file name and whether it is saved. Files saved only on your computer can't use AutoSave. The web apps always save as you work and don't have an AutoSave switch."},{type:"callout",variant:"info",text:"When AutoSave is on, the desktop apps call File › Save As by a different name, Save a Copy, because the original is already saving itself. Use Save a Copy when you want a separate file, such as a template's starting point."},{type:"drag-drop",mode:"match",title:"Match the situation to what to do",prompt:"Drag each action onto the situation it fits.",items:[{id:"a",text:"AutoSave is off on a file in OneDrive",match:"Turn AutoSave on in the title bar"},{id:"b",text:"You need a separate starting copy",match:"File › Save a Copy"},{id:"c",text:"You need yesterday's version back",match:"Select the file name in the title bar › Version History"},{id:"d",text:"A brand-new document",match:"Save it to OneDrive first, so AutoSave can work"}]}]},{heading:"Saving new files to OneDrive",blocks:[{type:"list",ordered:!0,items:["In a new document, select File › Save As (or press Ctrl+S).","Choose OneDrive - Lakeside Medical Associates (or OneDrive - Personal for your own files).","Pick the folder, type a clear name, and select Save.","AutoSave turns on, and the title bar shows that the file is saved to OneDrive."]},{type:"tip",text:"Select the file name in the title bar of a desktop app to see where the file is saved, rename it, or open Version History."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"AutoSave is greyed out for a document you just created on the desktop. What is the most likely reason?",options:["AutoSave is broken","The document isn't saved to OneDrive or SharePoint yet","You opened it in the browser","Someone else is editing it"],correctIndex:1,explanation:"AutoSave works for files stored in OneDrive or SharePoint. Save the file there first.",optionRationales:["It's a matter of where the file is saved.","Correct.","Web apps save automatically and don't show the switch.","Co-authoring doesn't disable AutoSave."]},{type:"knowledge-check",question:"With AutoSave on, why does the File menu show Save a Copy instead of Save As?",options:["Save As was removed from Office","The original is already saving itself, so the command makes a separate copy","You need a different subscription","It only appears in Excel"],correctIndex:1,explanation:"AutoSave keeps saving the original, so the command for a separate file is called Save a Copy.",optionRationales:["It is renamed, not removed.","Correct.","It's about AutoSave, not your subscription.","It appears in Word, Excel, and PowerPoint."]}]}],challenge:[{type:"paragraph",text:"Use AutoSave and version history with a practice file."},{type:"list",ordered:!0,items:["Create a new Word document on the computer, type one sentence, and save it to OneDrive with a clear name. Take a screenshot of the title bar showing AutoSave on.","Type a second sentence and wait a few seconds for AutoSave.","Select the file name in the title bar and open Version History. Take a screenshot of the versions.","If the computer doesn't have the Word desktop app, do the same in Word for the web: File › Info › Version History."]},{type:"callout",variant:"success",text:"Deliverable: Submit your two screenshots to your instructor or course folder. If you cannot sign in or save to OneDrive, submit this lesson's practice simulation results page instead."}]}],level:"Intermediate",estimatedMinutes:40}]}};